# 고3 생물의 유전(22개정 진로선택) h-biogen 후반부 유형 35개 × 6문항 — 유전자 발현·발현 조절·생명공학기술·생명윤리
# 코돈 해독·번역·돌연변이·PCR·제한 효소 지도·DNA 지문 등 계산은 모두 아래에서 파이썬으로 검산(assert)한다.
# 그림 없이 풀리도록 서열·표·말로 자료를 완전히 서술한다. 코돈표는 문제에 필요한 코돈만 준다.
