WR = {'ㄱ': ['ㄷ', 'ㄱ, ㄴ', 'ㄴ, ㄷ', 'ㄱ, ㄴ, ㄷ'],
      'ㄴ': ['ㄱ', 'ㄷ', 'ㄱ, ㄴ', 'ㄴ, ㄷ'],
      'ㄷ': ['ㄱ', 'ㄱ, ㄴ', 'ㄴ, ㄷ', 'ㄱ, ㄴ, ㄷ'],
      'ㄱ, ㄴ': ['ㄱ', 'ㄷ', 'ㄴ, ㄷ', 'ㄱ, ㄴ, ㄷ'],
      'ㄱ, ㄷ': ['ㄱ', 'ㄴ', 'ㄴ, ㄷ', 'ㄱ, ㄴ, ㄷ'],
      'ㄴ, ㄷ': ['ㄱ', 'ㄷ', 'ㄱ, ㄴ', 'ㄱ, ㄴ, ㄷ'],
      'ㄱ, ㄴ, ㄷ': ['ㄱ', 'ㄷ', 'ㄱ, ㄴ', 'ㄴ, ㄷ']}
HB_ANS = collections.Counter()


def HB(tid, d, head, items, pre=(), expect=None):
    """<보기> 합답형 — items = [(진술, 참/거짓, 까닭), ...] 로 정답과 해설의 옳음/옳지 않음을 기계가 정한다."""
    assert len(items) == 3
    ans = ', '.join('ㄱㄴㄷ'[i] for i, (_, t, _r) in enumerate(items) if t)
    assert ans, head[:30]
    if expect is not None:
        assert ans == expect, (tid, ans, expect)
    body = (head + '\n\n<보기>\n' + '\n'.join(f'{"ㄱㄴㄷ"[i]}. {s}' for i, (s, _t, _r) in enumerate(items)))
    steps = list(pre) + [f'{"ㄱㄴㄷ"[i]}: {r}({"옳음" if t else "옳지 않음"}).' for i, (_s, t, r) in enumerate(items)]
    HB_ANS[ans] += 1
    q(tid, d, body, ans, WR[ans], steps + [f'옳은 것은 {ans}이다.'])


# ── 유전 암호 도구 ─────────────────────────────────────────
BASES = 'UCAG'
_AA = 'FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
CODE = {a + b + c: _AA[16 * i + 4 * j + k] for i, a in enumerate(BASES) for j, b in enumerate(BASES) for k, c in enumerate(BASES)}
assert CODE['AUG'] == 'M' and CODE['UGG'] == 'W' and CODE['UGA'] == '*' and CODE['UAA'] == '*' and CODE['UAG'] == '*'
assert CODE['UUU'] == 'F' and CODE['AAA'] == 'K' and CODE['CCC'] == 'P' and CODE['GGG'] == 'G' and CODE['GAU'] == 'D'
assert CODE['CAU'] == 'H' and CODE['AGA'] == 'R' and CODE['AGU'] == 'S' and CODE['AUA'] == 'I' and CODE['UGU'] == 'C'
assert CODE['CAA'] == 'Q' and CODE['AAU'] == 'N' and CODE['GCU'] == 'A' and CODE['ACU'] == 'T' and CODE['GUG'] == 'V'
assert sum(v == '*' for v in CODE.values()) == 3 and len(set(CODE.values())) == 21
KOR = {'F': '페닐알라닌', 'L': '류신', 'I': '아이소류신', 'M': '메싸이오닌', 'V': '발린', 'S': '세린', 'P': '프롤린',
       'T': '트레오닌', 'A': '알라닌', 'Y': '타이로신', 'H': '히스티딘', 'Q': '글루타민', 'N': '아스파라진', 'K': '라이신',
       'D': '아스파트산', 'E': '글루탐산', 'C': '시스테인', 'W': '트립토판', 'R': '아르지닌', 'G': '글라이신', '*': '종결 코돈'}
_CP = {'A': 'T', 'T': 'A', 'G': 'C', 'C': 'G'}
_CPR = {'A': 'U', 'U': 'A', 'G': 'C', 'C': 'G'}


def rc(dna):
    """DNA 상보 가닥(5'→3' 으로 다시 씀)"""
    return ''.join(_CP[c] for c in reversed(dna))


def rcr(rna):
    """RNA 상보 서열(5'→3')"""
    return ''.join(_CPR[c] for c in reversed(rna))


def comp(dna):
    """같은 자리 상보 염기(방향 표기는 반대로 붙인다)"""
    return ''.join(_CP[c] for c in dna)


def r2d(rna):
    return rna.replace('U', 'T')


def d2r(dna):
    return dna.replace('T', 'U')


def orf(mrna):
    """5' 쪽 첫 AUG 부터 종결 코돈 직전까지 → (아미노산 문자열, 시작 index). 종결 코돈이 없으면 None"""
    i = mrna.find('AUG')
    if i < 0:
        return None
    out = ''
    for k in range(i, len(mrna) - 2, 3):
        a = CODE[mrna[k:k + 3]]
        if a == '*':
            return out, i
        out += a
    return None


def codons(mrna):
    """번역에 쓰이는 코돈 목록(종결 코돈 포함)"""
    r = orf(mrna)
    assert r
    i = r[1]
    out = []
    for k in range(i, len(mrna) - 2, 3):
        out.append(mrna[k:k + 3])
        if CODE[out[-1]] == '*':
            return out
    raise AssertionError


def pep(s):
    return '–'.join(KOR[c] for c in s)


def ctab(cs, extra=()):
    """필요한 코돈만 담은 코돈표 문자열"""
    seen = sorted(set(list(cs) + list(extra)))
    return '| 코돈 | 아미노산 |\n' + '\n'.join(f'| {c} | {KOR[CODE[c]]} |' for c in seen)


def sp(s, k=3):
    return ' '.join(s[i:i + k] for i in range(0, len(s), k))


