T = 'u1m0s0t3'
assert rcr('AUG') == 'CAU' and d2r(rc('ATG')) == 'CAU'
q(T, 1, "DNA 주형 가닥의 염기 서열이 3'-TAC-5'이다. 이 부분에서 전사된 mRNA의 코돈과, 이 코돈에 결합하는 tRNA의 안티코돈을 옳게 짝지은 것은?",
  "코돈 5'-AUG-3', 안티코돈 5'-CAU-3'",
  ["코돈 5'-UAC-3', 안티코돈 5'-AUG-3'", "코돈 5'-AUG-3', 안티코돈 5'-UAC-3'",
   "코돈 5'-ATG-3', 안티코돈 5'-CAT-3'", "코돈 5'-GUA-3', 안티코돈 5'-UAC-3'"],
  ["주형 가닥 3'-TAC-5'과 상보적인 mRNA는 5'-AUG-3'이다(RNA에는 T 대신 U).",
   "안티코돈은 코돈과 역평행으로 결합하므로 3'-UAC-5', 즉 5'→3' 방향으로 쓰면 5'-CAU-3'이다.",
   "안티코돈을 5'-UAC-3'로 쓰면 방향이 거꾸로 된 것이고, RNA에는 T가 없다."])

_cs = 'ATGCCAGTT'
_mr = d2r(_cs)
assert _mr == 'AUGCCAGUU' and d2r(rc(_cs)) == 'AACUGGCAU'
q(T, 2, f"어떤 유전자의 비주형 가닥(주형 가닥의 상보 가닥) 일부가 5'-{_cs}-3'이다. 이 부분의 주형 가닥으로부터 전사된 mRNA의 염기 서열은?",
  f"5'-{_mr}-3'",
  [f"5'-{''.join(_CPR[c] for c in _mr)}-3'", f"5'-{d2r(rc(_cs))}-3'", f"3'-{_mr}-5'", f"5'-{_cs}-3'"],
  ['mRNA는 주형 가닥과 상보적이므로, 주형 가닥의 상보 가닥인 비주형 가닥과 염기 서열·방향이 같다. 다만 T 대신 U가 들어간다.',
   f"따라서 mRNA는 5'-{_mr}-3'이다.",
   "5'-AACUGGCAU-3'은 비주형 가닥을 주형으로 착각한 것이고, 5'-ATGCCAGTT-3'은 U 대신 T를 쓴 DNA 서열이다."])

_ac = ['CAU', 'GGC', 'UUU']
_mr = ''.join(rcr(a) for a in _ac)
_tmp = rc(r2d(_mr))
assert _mr == 'AUGGCCAAA' and _tmp == 'TTTGGCCAT'
_w = ['TACCGGTTT', 'ATGGCCAAA', 'CATGGCTTT', 'AAACCGGTA']
assert _tmp not in _w and len(set(_w)) == 4
q(T, 3, "어떤 폴리펩타이드가 합성될 때 tRNA가 다음 순서대로 리보솜에 들어왔고, 각 tRNA의 안티코돈(5'→3')은 다음과 같았다.\n\n"
  "첫째: 5'-CAU-3' → 둘째: 5'-GGC-3' → 셋째: 5'-UUU-3'\n\n"
  '이 세 아미노산을 지정하는 DNA 주형 가닥 부분의 염기 서열을 5\'→3\' 방향으로 옳게 나타낸 것은?',
  f"5'-{_tmp}-3'", [f"5'-{x}-3'" for x in _w],
  ["안티코돈과 역평행으로 결합하는 코돈은 5'-AUG-3', 5'-GCC-3', 5'-AAA-3'이므로 mRNA는 5'-AUGGCCAAA-3'이다.",
   "주형 가닥은 mRNA와 상보적이고 역평행이므로 3'-TACCGGTTT-5', 즉 5'→3'으로 쓰면 5'-TTTGGCCAT-3'이다.",
   "5'-TACCGGTTT-3'은 방향을 뒤집지 않은 것이고, 5'-CATGGCTTT-3'은 안티코돈을 그대로 이어 쓴 것이다."])

q(T, 3, 'DNA 주형 가닥, mRNA, tRNA의 염기 서열 관계에 대한 설명으로 옳지 «않은» 것은?',
  'tRNA의 안티코돈은 DNA 비주형 가닥의 해당 부분과 염기 서열이 같다(T 대신 U).',
  ['mRNA의 코돈은 DNA 주형 가닥의 해당 부분과 상보적이다.',
   'mRNA의 염기 서열은 DNA 비주형 가닥에서 T를 U로 바꾼 것과 같다.',
   '안티코돈은 코돈과 역평행으로 상보 결합한다.',
   '하나의 tRNA는 한 종류의 아미노산만 운반한다.'],
  ['비주형 가닥 = mRNA(T→U)이고, 안티코돈은 mRNA 코돈과 상보적이므로 안티코돈은 비주형 가닥이 아니라 주형 가닥과 같은 염기 배열(T→U)을 가진다.',
   '예: 주형 3\'-TAC-5\' → 코돈 5\'-AUG-3\' → 안티코돈 3\'-UAC-5\'.',
   '나머지 설명은 모두 옳다.'])

_cod = 'GCATGTGGCCGAAATAGTC'
_mr = d2r(_cod)
_r = orf(_mr)
assert _r[0] == 'MWPK' and orf(d2r(rc(_cod))) is None
_c3 = codons(_mr)[2]
assert _c3 == 'CCG' and rcr(_c3) == 'CGG'
q(T, 4, '다음은 어떤 DNA 이중 가닥의 염기 서열이다. Ⅰ과 Ⅱ 중 하나가 주형 가닥이며, 전사된 mRNA에서 5\' 쪽의 첫 AUG부터 번역이 시작되어 종결 코돈에서 끝난다.\n\n'
  f"가닥 Ⅰ: 5'-{_cod}-3'\n가닥 Ⅱ: 3'-{comp(_cod)}-5'\n\n{ctab(codons(_mr))}\n\n"
  "주형 가닥과, 이 폴리펩타이드의 세 번째 아미노산을 운반하는 tRNA의 안티코돈(5'→3')을 옳게 짝지은 것은?",
  "주형 가닥: Ⅱ, 안티코돈: 5'-CGG-3'",
  ["주형 가닥: Ⅰ, 안티코돈: 5'-CGG-3'", "주형 가닥: Ⅱ, 안티코돈: 5'-GGC-3'",
   "주형 가닥: Ⅱ, 안티코돈: 5'-CCG-3'", "주형 가닥: Ⅰ, 안티코돈: 5'-GCC-3'"],
  [f"Ⅱ를 주형으로 하면 mRNA는 5'-{_mr}-3'이고, AUG UGG CCG AAA UAG로 읽혀 {pep(_r[0])}이 합성된다.",
   "Ⅰ을 주형으로 한 mRNA(5'-GACUAUUUCGGCCACAUGC-3')는 AUG 뒤에 종결 코돈이 없어 조건에 맞지 않는다.",
   "세 번째 코돈은 5'-CCG-3'(프롤린)이므로 안티코돈은 3'-GGC-5', 즉 5'-CGG-3'이다. 5'-GGC-3'은 방향을 뒤집지 않은 것이다."])

_mr = 'GAUGGCCAAGUGGUAAC'
_r = orf(_mr)
_tmp = rc(r2d(_mr))
assert _r[0] == 'MAKW' and _tmp == 'GTTACCACTTGGCCATC'
assert rcr('AAG') == 'CUU' and rc('TGG') == 'CCA'
HB(T, 5, f"다음은 어떤 유전자의 DNA 주형 가닥 일부를 5'→3' 방향으로 나타낸 것이다. 이로부터 전사된 mRNA에서 첫 AUG부터 번역이 시작된다.\n\n"
   f"주형 가닥: 5'-{_tmp}-3'\n\n{ctab(codons(_mr))}\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은?",
   [('합성되는 폴리펩타이드는 5개의 아미노산으로 이루어진다.', False,
     f"mRNA는 주형 가닥의 상보 서열인 5'-{_mr}-3'이고, AUG GCC AAG UGG UAA로 읽혀 {pep(_r[0])}, 즉 4개의 아미노산으로 이루어진다"),
    ("라이신을 운반하는 tRNA의 안티코돈은 5'-CUU-3'이다.", True,
     "라이신 코돈 5'-AAG-3'과 역평행으로 결합하는 안티코돈은 3'-UUC-5', 즉 5'-CUU-3'이다"),
    ("주형 가닥에서 트립토판 코돈에 대응하는 부분의 염기 서열은 5'-TGG-3'이다.", False,
     "트립토판 코돈 5'-UGG-3'에 대응하는 주형 가닥 부분은 3'-ACC-5', 즉 5'-CCA-3'이다")],
   pre=["주형 가닥을 3'→5'으로 뒤집어 상보 염기를 쓰면 mRNA를 얻는다."], expect='ㄴ')

# ═══════════════════════════════════════════════════════════
# T3  u1m0s0t4  진핵생물 RNA 가공 과정 해석
# ═══════════════════════════════════════════════════════════
T = 'u1m0s0t4'
q(T, 1, '진핵세포에서 일어나는 RNA 가공에 대한 설명으로 옳은 것은?',
  '1차 전사체에서 인트론이 제거되고 엑손끼리 연결되는 과정을 RNA 스플라이싱이라고 한다.',
  ['RNA 가공은 세포질의 리보솜에서 일어난다.',
   '원핵생물의 mRNA도 인트론이 제거되는 가공 과정을 거친다.',
   '엑손이 제거되고 인트론끼리 연결되어 성숙한 mRNA가 된다.',
   "mRNA의 5' 말단에 폴리 A 꼬리가 붙는다."],
  ['진핵세포의 1차 전사체(처음 전사된 RNA)는 핵 안에서 가공된다. 인트론을 잘라 내고 엑손을 이어 붙이는 과정이 RNA 스플라이싱이다.',
   "5' 말단에는 모자(캡) 구조, 3' 말단에는 폴리 A 꼬리가 붙는다.",
   '원핵생물은 대개 인트론이 없고, 전사와 번역이 세포질에서 거의 동시에 일어난다.'])

_ex, _in = [120, 90, 150], [300, 250]
_mat, _tot = sum(_ex), sum(_ex) + sum(_in)
assert (_mat, _tot) == (360, 910)
_w = [_tot, sum(_in), _mat + 300, _mat + 250]
assert _mat not in _w and len(set(_w)) == 4
q(T, 2, '어떤 진핵생물 유전자의 1차 전사체는 다음과 같이 5개 부위로 이루어져 있다.\n\n'
  "5'-[엑손 1: 120개]-[인트론 1: 300개]-[엑손 2: 90개]-[인트론 2: 250개]-[엑손 3: 150개]-3' (단위: 뉴클레오타이드)\n\n"
  'RNA 가공이 끝난 성숙한 mRNA의 뉴클레오타이드 수는? (단, 모자 구조와 폴리 A 꼬리는 고려하지 않는다.)',
  f'{_mat}개', [f'{x}개' for x in _w],
  ['RNA 스플라이싱으로 인트론은 모두 제거되고 엑손만 연결된다.',
   f'성숙한 mRNA = 엑손 1 + 엑손 2 + 엑손 3 = 120 + 90 + 150 = {_mat}개이다.',
   f'{_tot}개는 1차 전사체 전체, {sum(_in)}개는 인트론의 합이며, {_mat + 300}개·{_mat + 250}개는 인트론을 하나만 제거한 값이다.'])

q(T, 3, '원핵생물과 진핵생물의 유전자 발현을 비교한 설명으로 옳지 «않은» 것은?',
  '진핵생물에서 성숙한 mRNA의 뉴클레오타이드 수는 그 유전자의 1차 전사체의 뉴클레오타이드 수와 항상 같다.',
  ['원핵생물은 핵막이 없어 전사가 끝나기 전에 번역이 시작될 수 있다.',
   '진핵생물에서 전사는 핵 안에서, 번역은 세포질에서 일어난다.',
   "진핵생물의 mRNA에는 5' 모자 구조와 3' 폴리 A 꼬리가 첨가된다.",
   '진핵생물의 엑손은 가공이 끝난 성숙한 mRNA에 남는 부분이다.'],
  ['진핵생물의 1차 전사체에서는 인트론이 제거되므로, 인트론이 있는 유전자의 성숙한 mRNA는 1차 전사체보다 짧다.',
   '원핵생물은 전사와 번역이 모두 세포질에서 일어나 동시에 진행될 수 있다.',
   '진핵생물은 핵에서 전사·가공된 mRNA가 세포질로 나가 번역된다.'])

_opt = ['엑손 2', '엑손 3']
_forms = [('엑손 1',) + tuple(x for x, k in zip(_opt, pick) if k) + ('엑손 4',) for pick in itertools.product([0, 1], repeat=2)]
assert len(set(_forms)) == 4
q(T, 3, '어떤 진핵생물 유전자는 엑손 1~4를 가진다. 이 유전자의 1차 전사체가 가공될 때 엑손 1과 엑손 4는 항상 포함되고, 엑손 2와 엑손 3은 각각 포함되거나 빠질 수 있다. 이 유전자로부터 만들어질 수 있는 성숙한 mRNA의 종류는 최대 몇 가지인가? (단, 엑손의 배열 순서는 바뀌지 않고, 인트론은 모두 제거된다.)',
  '4가지', ['1가지', '2가지', '3가지', '8가지'],
  ['엑손 2의 포함 여부 2가지 × 엑손 3의 포함 여부 2가지 = 4가지이다.',
   '가능한 조합: 1-2-3-4, 1-2-4, 1-3-4, 1-4.',
   '이처럼 엑손을 선택적으로 연결하는 것을 선택적 RNA 스플라이싱이라 하며, 하나의 유전자로 여러 종류의 폴리펩타이드를 만들 수 있게 한다.'])

_gene, _mat, _loops = 2400, 900, [500, 600]
_x = _gene - _mat - sum(_loops)
assert _x == 400 and _x > 0
q(T, 4, '다음은 어떤 진핵생물 유전자에 대한 실험이다.\n\n'
  '(가) 이 유전자에서 전사되는 부위의 DNA 주형 가닥은 2,400개의 뉴클레오타이드로 이루어져 있다.\n'
  '(나) 이 유전자의 성숙한 mRNA(모자 구조와 폴리 A 꼬리 제외)는 900개의 뉴클레오타이드로 이루어져 있다.\n'
  '(다) (가)의 주형 가닥과 (나)의 mRNA를 섞어 상보적으로 결합시켰더니, 주형 가닥 중 mRNA와 결합하지 못한 부분이 고리 3개를 이루었고, 고리의 길이는 각각 500, 600, ㉠개의 뉴클레오타이드였다.\n\n'
  '이 유전자의 엑손 수와 ㉠을 옳게 짝지은 것은? (단, 전사되는 부위의 양 끝은 엑손이다.)',
  f'엑손 4개, ㉠ = {_x}',
  [f'엑손 3개, ㉠ = {_x}', f'엑손 4개, ㉠ = {_gene - sum(_loops)}', f'엑손 3개, ㉠ = {_gene - sum(_loops)}', f'엑손 2개, ㉠ = {_x}'],
  ['mRNA와 결합하지 못하고 고리로 튀어나온 부분은 성숙한 mRNA에 없는 인트론이다. 고리가 3개이므로 인트론 3개이다.',
   '양 끝이 엑손이고 인트론 3개가 엑손 사이에 있으므로 엑손은 4개이다.',
   f'인트론 합 = 2,400 − 900 = 1,500이므로 ㉠ = 1,500 − 500 − 600 = {_x}이다. 1,300은 mRNA 길이를 빼지 않은 값이다.'])

_e1, _i1, _e2, _i2, _e3 = 150, 400, 210, 350, 240
_utr5, _utr3 = 60, 81
_codingnt = (_e1 - _utr5) + _e2 + (_e3 - _utr3)
_aa = _codingnt // 3 - 1
assert _codingnt % 3 == 0 and _codingnt == 459 and _aa == 152
assert _e1 + _e2 + _e3 == 600 and _i1 + _i2 == 750
HB(T, 5, '어떤 진핵생물 유전자의 1차 전사체는 다음과 같다.\n\n'
   f"5'-[엑손 1: {_e1}개]-[인트론 1: {_i1}개]-[엑손 2: {_e2}개]-[인트론 2: {_i2}개]-[엑손 3: {_e3}개]-3' (단위: 뉴클레오타이드)\n\n"
   f"• 개시 코돈은 엑손 1의 5' 끝에서 {_utr5 + 1}번째 뉴클레오타이드부터 시작한다.\n"
   f"• 엑손 3의 3' 끝 쪽 {_utr3}개 뉴클레오타이드는 종결 코돈 뒤에 있어 번역되지 않는다.\n\n"
   '이에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은? (단, 모자 구조와 폴리 A 꼬리는 고려하지 않으며, 돌연변이는 없다.)',
   [(f'성숙한 mRNA는 {_e1 + _e2 + _e3}개의 뉴클레오타이드로 이루어진다.', True,
     f'엑손만 남으므로 {_e1} + {_e2} + {_e3} = {_e1 + _e2 + _e3}개이다'),
    (f'이 유전자로부터 합성되는 폴리펩타이드는 {_aa + 1}개의 아미노산으로 이루어진다.', False,
     f'번역되는 부위(개시~종결 코돈) = ({_e1} − {_utr5}) + {_e2} + ({_e3} − {_utr3}) = {_codingnt}개 = 코돈 {_codingnt // 3}개이며, 종결 코돈은 아미노산을 지정하지 않으므로 {_aa}개이다'),
    ('1차 전사체에서 인트론을 이루는 뉴클레오타이드 수는 엑손을 이루는 뉴클레오타이드 수보다 많다.', True,
     f'인트론 {_i1 + _i2}개 > 엑손 {_e1 + _e2 + _e3}개이다')],
   expect='ㄱ, ㄷ')

# ═══════════════════════════════════════════════════════════
# T4  u1m0s1t0  리보솜과 tRNA 역할 이해
# ═══════════════════════════════════════════════════════════
T = 'u1m0s1t0'
q(T, 1, 'tRNA에 대한 설명으로 옳은 것은?',
  '한쪽 끝에 특정 아미노산이 결합하고, 다른 쪽에 mRNA의 코돈과 상보적인 안티코돈이 있다.',
  ['리보솜을 구성하는 주된 RNA이다.',
   'DNA의 유전 정보를 복사하여 핵에서 리보솜으로 전달한다.',
   '두 가닥이 꼬인 이중 나선 구조의 DNA이다.',
   '아미노산 사이의 펩타이드 결합을 끊어 단백질을 분해한다.'],
  ['tRNA는 아미노산을 리보솜으로 운반하는 RNA로, 3\' 말단에 아미노산이 결합하고 안티코돈으로 mRNA의 코돈을 인식한다.',
   '리보솜을 구성하는 RNA는 rRNA, 유전 정보를 전달하는 RNA는 mRNA이다.',
   'tRNA는 한 가닥 RNA가 접혀 부분적으로 염기쌍을 이룬 구조이다.'])

q(T, 2, '리보솜에 대한 설명으로 옳은 것은?',
  'rRNA와 단백질로 이루어져 있으며, 큰 단위체와 작은 단위체로 구성된다.',
  ['DNA와 히스톤 단백질로 이루어져 있다.',
   '인지질 이중층 막으로 둘러싸인 세포 소기관이다.',
   '원핵세포에는 리보솜이 없다.',
   '하나의 단위체로 이루어져 mRNA 없이 단독으로 단백질을 합성한다.'],
  ['리보솜은 rRNA와 단백질로 된 큰 단위체와 작은 단위체로 이루어지며, 번역이 시작될 때 mRNA에 두 단위체가 결합한다.',
   'DNA와 히스톤 단백질로 된 것은 염색질(뉴클레오솜)이다.',
   '리보솜은 막이 없는 구조물이며, 원핵세포와 진핵세포 모두에 있다.'])

q(T, 3, '리보솜의 A 자리, P 자리, E 자리에 대한 설명으로 옳은 것은?',
  '신장 과정에서 새 아미노산을 운반해 온 tRNA는 A 자리에 결합한다.',
  ['번역이 시작될 때 개시 tRNA는 A 자리에 결합한다.',
   '아미노산을 내려놓은 tRNA는 A 자리에서 리보솜을 떠난다.',
   '펩타이드 결합은 E 자리의 아미노산과 A 자리의 아미노산 사이에 형성된다.',
   '종결 코돈이 A 자리에 오면 종결 코돈과 상보적인 안티코돈을 가진 tRNA가 결합한다.'],
  ['새 아미노산을 운반한 tRNA는 A 자리로 들어오고, 폴리펩타이드 사슬이 붙은 tRNA는 P 자리에 있으며, 아미노산을 내려놓은 tRNA는 E 자리에서 떠난다.',
   '개시 tRNA는 처음부터 P 자리에 결합한다.',
   '펩타이드 결합은 P 자리 tRNA의 사슬과 A 자리 tRNA의 아미노산 사이에 형성되며, 종결 코돈에는 tRNA가 아니라 방출 인자가 결합한다.'])

q(T, 3, '번역에 관여하는 tRNA와 리보솜에 대한 설명으로 옳지 «않은» 것은?',
  '안티코돈이 같은 tRNA라도 운반하는 아미노산의 종류는 서로 다를 수 있다.',
  ['tRNA에 아미노산이 결합하는 과정에는 효소와 ATP가 필요하다.',
   '아미노산을 내려놓은 tRNA는 다시 아미노산과 결합하여 재사용될 수 있다.',
   '하나의 mRNA에 여러 개의 리보솜이 결합하여 동시에 번역할 수 있다.',
   'tRNA와 rRNA는 모두 DNA로부터 전사되어 만들어진다.'],
  ['안티코돈이 같으면 결합하는 코돈이 같고, 한 코돈은 한 종류의 아미노산만 지정하므로 그 tRNA가 운반하는 아미노산도 한 종류로 정해진다.',
   'tRNA에 알맞은 아미노산을 붙이는 효소가 ATP의 에너지를 이용한다. tRNA는 재사용된다.',
   '한 mRNA에 여러 리보솜이 붙어(폴리솜) 짧은 시간에 많은 폴리펩타이드를 만든다. tRNA와 rRNA도 DNA에서 전사된다.'])

_m = 'AUGGGCUUCGGCUAA'
_cs = codons(_m)
_aa_codons = _cs[:-1]
_kinds = len(set(_aa_codons))
_a_entries = len(_aa_codons) - 1
assert orf(_m)[0] == 'MGFG' and _kinds == 3 and _a_entries == 3
q(T, 4, f"mRNA 5'-{sp(_m)}-3'이 번역되어 폴리펩타이드가 합성되었다.\n\n{ctab(_cs)}\n\n"
  '이 번역 과정에서 리보솜의 A 자리에 tRNA가 결합한 횟수와, 번역에 사용된 tRNA의 종류 수를 옳게 짝지은 것은? (단, 한 종류의 코돈에는 한 종류의 tRNA만 결합한다.)',
  f'{_a_entries}회, {_kinds}종류',
  [f'{_a_entries + 1}회, {_kinds}종류', f'{_a_entries + 1}회, {_kinds + 1}종류', f'{_a_entries + 2}회, {_kinds + 1}종류', f'{_a_entries}회, {_kinds + 1}종류'],
  [f'코돈은 AUG GGC UUC GGC UAA이며, 합성되는 폴리펩타이드는 {pep(orf(_m)[0])}이다.',
   f'개시 tRNA는 처음부터 P 자리에 결합하므로, A 자리로 들어오는 tRNA는 2~4번째 코돈의 tRNA {_a_entries}개이다. 종결 코돈(UAA)에는 방출 인자가 결합한다.',
   f'GGC가 두 번 나오므로 tRNA 종류는 AUG, GGC, UUC에 결합하는 {_kinds}종류이다.'])

HB(T, 5, '번역 과정에서 리보솜과 tRNA의 작용에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은?',
   [("번역이 진행되는 동안 리보솜은 mRNA의 5' → 3' 방향으로 한 코돈씩 이동한다.", True,
     "리보솜은 mRNA를 5'에서 3' 방향으로 읽으며 3염기씩 이동한다"),
    ('펩타이드 결합은 P 자리 tRNA의 아미노산이 E 자리로 옮겨지면서 형성된다.', False,
     'P 자리 tRNA에 붙은 사슬이 A 자리 tRNA의 아미노산으로 옮겨지며 펩타이드 결합이 형성된다. E 자리는 빈 tRNA가 떠나는 자리이다'),
    ('아미노산 50개로 된 폴리펩타이드 1분자가 합성될 때 아미노산을 운반한 tRNA 분자는 개시 tRNA를 포함하여 모두 50개이다.', True,
     'tRNA 1분자는 아미노산 1개를 운반하므로 아미노산 50개에 tRNA 50개가 쓰인다(종결 코돈에는 tRNA가 결합하지 않는다)')],
   expect='ㄱ, ㄷ')

# ═══════════════════════════════════════════════════════════
# T5  u1m0s1t1  번역 개시·신장·종결 과정 분석
# ═══════════════════════════════════════════════════════════
T = 'u1m0s1t1'
q(T, 1, '번역의 개시 단계에 대한 설명으로 옳은 것은?',
  'mRNA에 리보솜 작은 단위체가 결합하고, 개시 코돈에 개시 tRNA가 결합한 뒤 큰 단위체가 결합한다.',
  ['종결 코돈에 방출 인자가 결합한다.',
   '개시 tRNA는 리보솜의 A 자리에 결합한다.',
   '개시 코돈은 UAA이며 아미노산을 지정하지 않는다.',
   '개시 단계에서 펩타이드 결합 2개가 먼저 형성된다.'],
  ['개시: 작은 단위체가 mRNA에 결합 → 메싸이오닌을 운반한 개시 tRNA가 개시 코돈 AUG에 결합 → 큰 단위체가 결합하여 개시 복합체가 완성된다(개시 tRNA는 P 자리).',
   '방출 인자의 결합은 종결 단계이다. UAA는 종결 코돈이다.',
   '펩타이드 결합은 신장 단계에서 형성된다.'])

_steps = {'가': '방출 인자가 종결 코돈에 결합하여 폴리펩타이드가 떨어져 나온다.',
          '나': '리보솜 작은 단위체가 mRNA에 결합하고, 개시 tRNA가 개시 코돈에 결합한다.',
          '다': 'A 자리에 들어온 아미노산과 펩타이드 결합이 형성되고 리보솜이 한 코돈만큼 이동한다.',
          '라': '리보솜 큰 단위체가 결합하여 개시 복합체가 완성된다.'}
_ch = ['(나) → (라) → (다) → (가)', '(라) → (나) → (다) → (가)', '(나) → (다) → (라) → (가)', '(가) → (나) → (라) → (다)', '(나) → (라) → (가) → (다)']
_ord = ['(나) → (라) → (다) → (가)']
_ch2 = [_ch[1], _ch[2], _ord[0], _ch[3], _ch[4]]
qf(T, 2, '다음은 번역 과정의 일부를 순서 없이 나타낸 것이다.\n\n' + '\n'.join(f'({k}) {v}' for k, v in _steps.items()) +
   '\n\n번역이 일어나는 순서대로 옳게 나열한 것은?',
   _ch2, 2,
   ['개시: 작은 단위체와 개시 tRNA가 mRNA에 결합(나) → 큰 단위체가 결합(라).',
    '신장: 펩타이드 결합 형성과 리보솜 이동이 반복(다).',
    '종결: 종결 코돈에 방출 인자가 결합(가).'])

q(T, 3, '번역의 신장 단계에 대한 설명으로 옳은 것은?',
  "리보솜은 펩타이드 결합이 형성될 때마다 mRNA의 3' 쪽으로 한 코돈(염기 3개)만큼 이동한다.",
  ["리보솜은 mRNA의 3' → 5' 방향으로 이동한다.",
   '새 아미노산을 운반한 tRNA는 E 자리로 들어온다.',
   '펩타이드 결합 형성은 방출 인자가 촉매한다.',
   '리보솜이 한 번 이동할 때 mRNA 염기 1개씩 건너뛴다.'],
  ["신장 단계에서는 A 자리로 tRNA가 들어옴 → P 자리 사슬과 펩타이드 결합 → 리보솜이 3' 쪽으로 한 코돈 이동이 반복된다.",
   'tRNA는 A 자리로 들어오고 E 자리에서 떠난다.',
   '펩타이드 결합은 리보솜(큰 단위체)에서 형성되며, 방출 인자는 종결 단계에서 작용한다.'])

q(T, 3, '번역의 종결 단계에 대한 설명으로 옳지 «않은» 것은?',
  '종결 코돈과 상보적인 안티코돈을 가진 tRNA가 A 자리에 결합하여 번역이 끝난다.',
  ['종결 코돈이 리보솜의 A 자리에 오면 방출 인자가 결합한다.',
   '완성된 폴리펩타이드가 P 자리의 tRNA에서 떨어져 나온다.',
   '리보솜의 두 단위체가 mRNA에서 분리된다.',
   '종결 코돈에는 UAA, UAG, UGA가 있다.'],
  ['종결 코돈에 대응하는 tRNA는 없으며, 단백질인 방출 인자가 A 자리의 종결 코돈에 결합한다.',
   '그러면 폴리펩타이드가 tRNA에서 떨어져 나오고, 리보솜 단위체와 mRNA가 분리된다.',
   '종결 코돈은 UAA, UAG, UGA 세 가지이다.'])

_m = 'AUGUUUGGCAAAUGA'
_r = orf(_m)[0]
assert _r == 'MFGK'
_Pchain = 3; _bonds = _Pchain - 1
assert rcr('AAA') == 'UUU'
q(T, 4, f"mRNA 5'-{sp(_m)}-3'이 번역되고 있다.\n\n{ctab(codons(_m))}\n\n"
  '어느 시점에 리보솜의 P 자리에는 세 번째 코돈이, A 자리에는 네 번째 코돈이 위치하고, A 자리에 tRNA가 막 결합하였다(이 tRNA의 아미노산과 펩타이드 결합이 형성되기 전). 이 시점에 대한 설명으로 옳은 것은?',
  f'P 자리의 tRNA에는 아미노산 {_Pchain}개로 이루어진 사슬이 붙어 있다.',
  [f'지금까지 형성된 펩타이드 결합은 {_bonds + 1}개이다.',
   'A 자리의 tRNA는 글라이신을 운반해 왔다.',
   "A 자리 tRNA의 안티코돈은 5'-AAA-3'이다.",
   '이 mRNA에서 완성될 폴리펩타이드는 아미노산 5개로 이루어진다.'],
  [f'P 자리 tRNA에는 1~3번째 코돈의 아미노산(메싸이오닌–페닐알라닌–글라이신) {_Pchain}개가 이어진 사슬이 붙어 있고, 이들 사이의 펩타이드 결합은 {_bonds}개이다.',
   "A 자리의 네 번째 코돈은 AAA(라이신)이므로 tRNA는 라이신을 운반하며, 안티코돈은 5'-UUU-3'이다.",
   f'UGA는 종결 코돈이므로 완성된 폴리펩타이드는 {pep(_r)}, 아미노산 4개이다.'])

_m = 'GCAUGGCAUCCGAUUGGUAGCA'
_r = orf(_m)[0]
assert _r == 'MASDW'
HB(T, 5, f"mRNA 5'-{_m}-3'이 번역되어 폴리펩타이드 X가 합성되었다.\n\n{ctab(codons(_m))}\n\n"
   '이에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은? (단, 번역은 첫 AUG에서 시작한다.)',
   [(f'X가 합성될 때 펩타이드 결합은 {len(_r)}개 형성된다.', False,
     f'X는 {pep(_r)}이고 아미노산이 {len(_r)}개이므로 펩타이드 결합은 {len(_r) - 1}개이다'),
    (f'X가 합성되는 동안 리보솜의 A 자리에 결합한 tRNA는 {len(_r) - 1}개이다.', True,
     f'개시 tRNA는 P 자리에 결합하므로 A 자리로 들어온 tRNA는 2~{len(_r)}번째 아미노산을 운반한 {len(_r) - 1}개이다'),
    ('종결 코돈이 A 자리에 왔을 때 P 자리에는 트립토판을 운반해 온 tRNA가 있다.', True,
     '종결 코돈 UAG 바로 앞 코돈은 UGG(트립토판)이므로, 그 tRNA가 완성된 사슬을 달고 P 자리에 있다')],
   pre=[f'첫 AUG부터 읽으면 AUG GCA UCC GAU UGG UAG이다.'], expect='ㄴ, ㄷ')

# ═══════════════════════════════════════════════════════════
# T6  u1m0s1t2  폴리펩타이드 아미노산 서열 결정
# ═══════════════════════════════════════════════════════════
T = 'u1m0s1t2'
q(T, 1, '폴리펩타이드를 이루는 아미노산의 배열 순서를 직접 결정하는 것은?',
  'mRNA에 있는 코돈의 배열 순서',
  ['세포 안에 있는 tRNA의 종류 수', 'rRNA의 염기 서열', '리보솜을 이루는 단백질의 종류', 'DNA 비주형 가닥에 있는 인트론의 염기 서열'],
  ['리보솜은 mRNA의 코돈을 5\'→3\' 방향으로 차례로 읽고, 각 코돈에 맞는 아미노산을 tRNA가 운반해 와서 순서대로 연결한다.',
   '따라서 아미노산 서열은 mRNA 코돈의 배열 순서(궁극적으로는 DNA 주형 가닥의 염기 서열)로 결정된다.',
   'rRNA·리보솜 단백질은 번역 장치를 이루고, 인트론은 성숙한 mRNA에서 제거되므로 아미노산 서열을 결정하지 않는다.'])

_m = 'CCGAUGAAAGCUUAGGC'
_r = orf(_m)[0]
_first = ''.join(CODE[_m[i:i + 3]] for i in range(0, 12, 3))
assert _r == 'MKA' and _first == 'PMKA'
q(T, 2, f"다음 mRNA가 번역되어 만들어지는 폴리펩타이드의 아미노산 서열은? (단, 번역은 5' 쪽의 첫 AUG에서 시작한다.)\n\n"
  f"mRNA: 5'-{_m}-3'\n\n{ctab(['CCG', 'AUG', 'AAA', 'GCU', 'UAG'])}",
  pep(_r), [pep(_first), pep('KA'), pep(_r[::-1]), pep('MK')],
  ["5' 끝부터 3개씩 끊지 않고, 첫 AUG(4~6번째 염기)부터 읽기 틀을 잡는다.",
   f'AUG(메싸이오닌) AAA(라이신) GCU(알라닌) UAG(종결)이므로 {pep(_r)}이다.',
   "5' 끝의 CCG부터 읽은 프롤린–메싸이오닌–… 은 개시 코돈을 무시한 것이고, 개시 코돈도 메싸이오닌을 지정하므로 빼면 안 된다."])

_m = 'CUAUGACUUGGAAAGGCUGAUCC'
_r = orf(_m)[0]
_tmp = rc(r2d(_m))
assert _r == 'MTWKG' and _tmp == 'GGATCAGCCTTTCCAAGTCATAG'
_ignore_stop = _r + CODE['UCC']
q(T, 3, f"어떤 유전자의 DNA 주형 가닥 일부가 5'-{_tmp}-3'이다. 이 부분에서 전사된 mRNA의 첫 AUG부터 번역이 시작될 때, 합성되는 폴리펩타이드의 아미노산 서열은?\n\n"
  f"{ctab(codons(_m), ['UCC'])}",
  pep(_r), [pep(_ignore_stop), pep(_r[1:]), pep(_r[::-1]), pep('MT')],
  [f"주형 가닥을 3'→5' 방향으로 읽으며 상보 염기를 쓰면 mRNA 5'-{_m}-3'을 얻는다.",
   f'첫 AUG부터 AUG ACU UGG AAA GGC UGA로 읽혀 {pep(_r)}이 합성된다.',
   '종결 코돈 UGA 뒤의 UCC(세린)는 번역되지 않으며, 트립토판 코돈 UGG를 종결 코돈 UGA로 착각하지 않도록 주의한다.'])

_ok = 'AUGUGGAAGUGCUAA'
_bad = ['AUGUGGAAGUGAUAA', 'AUGUGGAAUUGCUAA', 'AUGUGCAAGUGGUAA', 'AUGUAGAAGUGCUAA']
assert orf(_ok)[0] == 'MWKC' and all(orf(b)[0] != 'MWKC' for b in _bad)
_cs_all = sorted({b[i:i + 3] for b in [_ok] + _bad for i in range(0, 15, 3)})
q(T, 3, f"다음 코돈표를 이용할 때, 아미노산 서열이 {pep('MWKC')}인 폴리펩타이드를 암호화하는 mRNA(5'→3')로 옳은 것은? (단, 제시된 서열의 첫 코돈부터 번역되며 마지막 코돈 뒤는 고려하지 않는다.)\n\n{ctab(_cs_all)}",
  f"5'-{sp(_ok)}-3'", [f"5'-{sp(b)}-3'" for b in _bad],
  [f"5'-{sp(_ok)}-3' = 메싸이오닌–트립토판–라이신–시스테인–종결로 조건에 맞다.",
   '…UGA UAA는 네 번째 코돈 UGA가 종결 코돈이어서 아미노산 3개에서 끝나고, AAU는 아스파라진을 지정한다.',
   'UGC와 UGG의 위치가 바뀐 서열은 메싸이오닌–시스테인–라이신–트립토판이 되고, 두 번째 코돈이 UAG이면 곧바로 종결된다.'])

_cod = 'GTATGAGTGCATTCTAAGG'
_up = rc(_cod)
_r = orf(d2r(_cod))[0]
_wrongstrand = d2r(_up)
_wr = ''.join(CODE[_wrongstrand[i:i + 3]] for i in range(_wrongstrand.find('AUG'), len(_wrongstrand) - 2, 3))
assert _r == 'MSAF' and orf(d2r(_up)) is None and _wr == 'MHSY'
q(T, 4, '다음은 어떤 DNA 이중 가닥의 염기 서열이다. 가닥 Ⅰ과 Ⅱ 중 하나가 주형 가닥이며, 전사된 mRNA에서 5\' 쪽의 첫 AUG부터 번역이 시작되어 종결 코돈에서 끝난다.\n\n'
  f"가닥 Ⅰ: 5'-{_up}-3'\n가닥 Ⅱ: 3'-{comp(_up)}-5'\n\n{ctab(['AUG', 'AGU', 'GCA', 'UUC', 'UAA', 'CAC', 'UCA', 'UAC'])}\n\n"
  '합성되는 폴리펩타이드의 아미노산 서열은?',
  pep(_r), [pep(_wr), pep(_r[::-1]), pep(_r[1:]), pep('MSA')],
  [f"Ⅱ를 주형으로 하면 mRNA는 가닥 Ⅰ과 같은 서열인 5'-{d2r(_up)}-3'이 되는데, AUG CAC UCA UAC 뒤에 종결 코돈이 없어 조건에 맞지 않는다.",
   f"Ⅰ을 주형으로 하면 mRNA는 가닥 Ⅱ를 5'→3'으로 읽은 5'-{d2r(_cod)}-3'이다.",
   f'첫 AUG부터 AUG AGU GCA UUC UAA로 읽혀 {pep(_r)}이 합성된다. 가닥 Ⅱ가 오른쪽이 5\' 끝임에 주의한다.'])

_m = 'GCAUGGCAAUGAAACCCUGGUAAGC'
_r = orf(_m)[0]
_mu = _m[:4] + 'A' + _m[5:]
assert _m[2:5] == 'AUG' and _mu[2:5] == 'AUA'
_rm = orf(_mu)[0]
assert _r == 'MAMKPW' and _r[2] == 'M' and _rm == 'MKPW'
HB(T, 5, f"다음은 어떤 mRNA의 염기 서열이다. 번역은 5' 쪽에서 가장 먼저 나오는 AUG에서 시작한다.\n\n5'-{_m}-3'\n\n{ctab(codons(_m), ['AUA'])}\n\n"
   '이에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은?',
   [(f'이 mRNA로부터 아미노산 {len(_r)}개로 된 폴리펩타이드가 합성된다.', True,
     f'첫 AUG부터 AUG GCA AUG AAA CCC UGG UAA로 읽히므로 {pep(_r)}, {len(_r)}개이다'),
    ('폴리펩타이드의 세 번째 아미노산은 메싸이오닌이다.', True,
     '세 번째 코돈이 AUG이므로 메싸이오닌이다(개시 코돈이 아닌 AUG는 메싸이오닌만 지정한다)'),
    (f'첫 번째 AUG의 G가 A로 바뀌어 AUA가 되면, 아미노산 {len(_rm)}개로 된 폴리펩타이드가 합성된다.', True,
     f'AUA(아이소류신)는 개시 코돈이 아니므로 그다음 AUG부터 AUG AAA CCC UGG UAA로 번역되어 {pep(_rm)}, {len(_rm)}개가 된다')],
   expect='ㄱ, ㄴ, ㄷ')

# ═══════════════════════════════════════════════════════════
# T7  u1m0s1t3  돌연변이 유형과 단백질 변화 분석
# ═══════════════════════════════════════════════════════════
T = 'u1m0s1t3'
q(T, 1, 'DNA에서 염기 1개가 삽입되거나 결실되어, 그 뒤에 있는 코돈의 읽기 틀이 모두 바뀌는 돌연변이를 무엇이라고 하는가?',
  '틀 이동(격자 이동) 돌연변이', ['침묵 돌연변이', '염색체 구조 이상', '미스센스(과오) 돌연변이', '넌센스 돌연변이'],
  ['코돈은 염기 3개 단위로 읽히므로 염기 1개(또는 3의 배수가 아닌 개수)가 삽입·결실되면 그 뒤의 읽기 틀이 모두 바뀐다. 이를 틀 이동 돌연변이라 한다.',
   '침묵·미스센스·넌센스 돌연변이는 주로 염기 하나의 치환으로 생긴다(아미노산 변화 없음/다른 아미노산/종결 코돈).',
   '염색체 구조 이상은 결실·중복·역위·전좌처럼 염색체 수준의 변화이다.'])

assert CODE['UGG'] == 'W' and CODE['UGA'] == '*'
q(T, 2, 'mRNA의 한 코돈 UGG(트립토판)가 염기 치환으로 UGA가 되었을 때 나타나는 결과로 옳은 것은? (단, UGA는 종결 코돈이다.)',
  '번역이 그 자리에서 끝나 폴리펩타이드가 정상보다 짧아진다.',
  ['트립토판이 다른 아미노산 하나로 바뀌고 길이는 같다.', '아미노산 서열에 아무 변화가 없다.',
   '그 뒤의 아미노산이 모두 바뀌지만 길이는 같다.', '폴리펩타이드가 정상보다 길어진다.'],
  ['아미노산을 지정하던 코돈이 종결 코돈으로 바뀌면 그 자리에서 번역이 끝난다(넌센스 돌연변이).',
   '따라서 그 코돈 앞까지의 아미노산만 연결된 짧은 폴리펩타이드가 만들어진다.',
   '다른 아미노산으로 바뀌는 것은 미스센스 돌연변이, 변화가 없는 것은 침묵 돌연변이이다.'])

_cands = [('CUU', 'CUC'), ('CUU', 'CCU'), ('CUU', 'UUU'), ('AAA', 'UAA'), ('GGA', 'GAA')]
assert CODE['CUU'] == CODE['CUC'] and all(CODE[a] != CODE[b] for a, b in _cands[1:])
q(T, 3, f'다음 코돈표를 참고할 때, 폴리펩타이드의 아미노산 서열이 변하지 «않는» 염기 치환은?\n\n{ctab([x for p in _cands for x in p])}',
  'CUU → CUC', ['CUU → CCU', 'CUU → UUU', 'AAA → UAA', 'GGA → GAA'],
  ['CUU와 CUC는 모두 류신을 지정하므로 아미노산이 바뀌지 않는다(침묵 돌연변이).',
   '이는 한 아미노산을 여러 코돈이 지정하는 유전 암호의 특성 때문이며, 코돈의 세 번째 염기가 바뀔 때 흔히 나타난다.',
   'CCU는 프롤린, UUU는 페닐알라닌, GAA는 글루탐산으로 바뀌고, UAA는 종결 코돈이 되어 번역이 멈춘다.'])

q(T, 3, '유전자 돌연변이가 단백질에 미치는 영향에 대한 설명으로 옳지 «않은» 것은?',
  '번역되는 부위에서 연속된 염기 3개가 결실되면 그 뒤의 아미노산 서열이 모두 바뀐다.',
  ['번역되는 부위에 염기 1개가 삽입되면 그 뒤의 읽기 틀이 바뀐다.',
   '염기 1개가 치환되면 아미노산이 바뀌거나, 바뀌지 않거나, 종결 코돈이 생길 수 있다.',
   '틀 이동 돌연변이가 일어나면 종결 코돈이 원래보다 앞이나 뒤에 나타날 수 있다.',
   '낫 모양 적혈구 빈혈증은 헤모글로빈 유전자의 염기 하나가 치환되어 아미노산 하나가 바뀐 결과이다.'],
  ['염기 3개(코돈 하나 분량)가 결실되면 읽기 틀은 유지되므로, 아미노산 1개가 빠지거나 결실 부위의 아미노산 하나 정도만 바뀌고 그 뒤 서열은 정상과 같다.',
   '염기 1개 삽입·결실은 틀 이동을 일으켜 뒤쪽 서열 전체가 바뀌고, 종결 코돈의 위치도 달라질 수 있다.',
   '낫 모양 적혈구 빈혈증은 β 사슬의 글루탐산이 발린으로 바뀐 치환 돌연변이이다.'])

_n = 'AUGUCAGAUAACUGGUAA'
_mu = _n[:3] + 'A' + _n[3:]
_rn, _rm = orf(_n)[0], orf(_mu)[0]
_nostop = ''.join(CODE[_mu[i:i + 3]] for i in range(0, 18, 3) if CODE[_mu[i:i + 3]] != '*')
assert _rn == 'MSDNW' and _rm == 'MIR' and _nostop == 'MIRLV'
q(T, 4, f"정상 유전자로부터 전사된 mRNA (가)의 번역 부위는 5'-{sp(_n)}-3'이다. 돌연변이 유전자에서는 (가)의 3번째와 4번째 염기 사이에 A 1개가 삽입된 mRNA가 만들어졌다.\n\n{ctab(codons(_n) + codons(_mu), ['CUG', 'GUA'])}\n\n"
  '돌연변이 mRNA로부터 합성되는 폴리펩타이드의 아미노산 서열은?',
  pep(_rm), [pep(_rn), pep('MISDNW'), pep(_nostop), pep('MI')],
  [f"돌연변이 mRNA는 5'-{sp(_mu)}-3'이 된다.",
   f'AUG(메싸이오닌) AUC(아이소류신) AGA(아르지닌) UAA(종결)이므로 {pep(_rm)}이다.',
   '염기 1개 삽입으로 읽기 틀이 바뀌어 원래 없던 종결 코돈이 앞쪽에 나타났다. 종결 코돈 뒤(CUG, GUA)는 번역되지 않는다.'])

_n = 'AUGCAAUGGGCAGUCAAGUAACUGA'
_a = _n[:8] + 'A' + _n[9:]
_b = _n[:11] + 'G' + _n[12:]
_c = _n[:9] + _n[10:]
_rn, _ra, _rb, _rcc = orf(_n)[0], orf(_a)[0], orf(_b)[0], orf(_c)[0]
assert _rn == 'MQWAVK' and _ra == 'MQ' and _rb == _rn and _rcc == 'MQWQSSN'
assert _n[6:9] == 'UGG' and _a[6:9] == 'UGA' and _n[9:12] == 'GCA' and _b[9:12] == 'GCG'
_tab = sorted({x for s in (_n, _a, _b, _c) for x in codons(s)})
HB(T, 5, f"정상 유전자의 mRNA 번역 부위와 그 뒤 서열은 5'-{_n}-3'이며, 첫 AUG부터 번역된다. 돌연변이 (가)~(다)는 이 mRNA에 다음 변화가 각각 하나씩 일어난 것이다.\n\n"
   '(가) 9번째 염기 G가 A로 치환\n(나) 12번째 염기 A가 G로 치환\n(다) 10번째 염기 G가 결실\n\n'
   f'{ctab(_tab)}\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은?',
   [('(가)에서 합성되는 폴리펩타이드의 펩타이드 결합 수는 2개이다.', False,
     f'(가)는 세 번째 코돈 UGG가 종결 코돈 UGA로 바뀌어 {pep(_ra)}(아미노산 2개)만 합성되므로 펩타이드 결합은 1개이다'),
    ('(나)는 아미노산 하나가 다른 아미노산으로 바뀌는 미스센스 돌연변이이다.', False,
     '(나)는 네 번째 코돈 GCA가 GCG로 바뀌는데 둘 다 알라닌이므로 아미노산 서열이 변하지 않는 침묵 돌연변이이다'),
    ('(다)에서 합성되는 폴리펩타이드는 정상 폴리펩타이드보다 아미노산 수가 많다.', True,
     f'(다)는 AUG CAA UGG CAG UCA AGU AAC UGA로 읽혀 {pep(_rcc)}(7개)가 되므로 정상({len(_rn)}개)보다 많다')],
   pre=[f'정상: AUG CAA UGG GCA GUC AAG UAA → {pep(_rn)}(6개).'], expect='ㄷ')

# ═══════════════════════════════════════════════════════════
# T8  u1m0s1t4  염기 서열로 아미노산 개수 계산
# ═══════════════════════════════════════════════════════════
T = 'u1m0s1t4'
_nc = 60
q(T, 1, f'어떤 mRNA에서 개시 코돈부터 종결 코돈까지의 부위가 코돈 {_nc}개로 이루어져 있다. 이 부위가 번역되어 만들어진 폴리펩타이드를 이루는 아미노산의 수는?',
  f'{_nc - 1}개', [f'{_nc}개', f'{_nc - 2}개', f'{_nc * 3}개', f'{_nc // 3}개'],
  ['개시 코돈(AUG)은 메싸이오닌을 지정하지만, 종결 코돈은 아미노산을 지정하지 않는다.',
   f'따라서 아미노산 수 = 코돈 수 − 1 = {_nc} − 1 = {_nc - 1}개이다.',
   '개시 코돈까지 빼서 58개로 계산하거나, 코돈 수를 그대로 60개로 답하지 않도록 주의한다.'])

_aa = 100
_nt = (_aa + 1) * 3
assert _nt == 303
q(T, 2, f'아미노산 {_aa}개로 이루어진 폴리펩타이드를 암호화하는 mRNA에서, 개시 코돈부터 종결 코돈까지의 부위를 이루는 뉴클레오타이드 수는?',
  f'{_nt}개', [f'{_aa * 3}개', f'{(_aa - 1) * 3}개', f'{_nt * 2}개', f'{_aa}개'],
  [f'아미노산 {_aa}개를 지정하는 코돈 {_aa}개와 종결 코돈 1개가 필요하므로 코돈은 {_aa + 1}개이다.',
   f'코돈 하나는 뉴클레오타이드 3개이므로 {_aa + 1} × 3 = {_nt}개이다.',
   f'{_aa * 3}개는 종결 코돈을 빠뜨린 값, {_nt * 2}개는 DNA 두 가닥의 뉴클레오타이드 수이다.'])

_aa = 150
_cod, _tnt = _aa + 1, (_aa + 1) * 3
assert (_cod, _tnt) == (151, 453)
q(T, 3, f'아미노산 {_aa}개로 이루어진 폴리펩타이드 1분자가 합성될 때, 번역에 이용된 mRNA의 코돈 수(종결 코돈 포함)와 이 부위에 대응하는 DNA 주형 가닥의 뉴클레오타이드 수를 옳게 짝지은 것은? (단, 인트론은 없다.)',
  f'코돈 {_cod}개, 뉴클레오타이드 {_tnt}개',
  [f'코돈 {_aa}개, 뉴클레오타이드 {_aa * 3}개', f'코돈 {_cod}개, 뉴클레오타이드 {_tnt * 2}개',
   f'코돈 {_aa - 1}개, 뉴클레오타이드 {(_aa - 1) * 3}개', f'코돈 {_cod}개, 뉴클레오타이드 {_cod}개'],
  [f'아미노산 {_aa}개 + 종결 코돈 1개 = 코돈 {_cod}개이다.',
   f'DNA 주형 가닥에서 이 코돈들에 대응하는 부분은 {_cod} × 3 = {_tnt}개의 뉴클레오타이드이다.',
   f'{_tnt * 2}개는 주형 가닥과 비주형 가닥을 모두 센 값이다.'])

_bp = 603
_aa = _bp // 3 - 1
_bond = _aa - 1
assert _bp % 3 == 0 and _aa == 200 and _bond == 199
q(T, 3, f'어떤 세균 유전자에서 개시 코돈부터 종결 코돈까지에 해당하는 DNA 부위는 {_bp}개의 염기쌍으로 이루어져 있다. 이 유전자로부터 합성되는 폴리펩타이드 1분자에 있는 펩타이드 결합의 수는?',
  f'{_bond}개', [f'{_aa}개', f'{_aa + 1}개', f'{_aa - 2}개', f'{(_bp * 2) // 3 - 1}개'],
  [f'염기쌍 {_bp}개는 코돈 {_bp // 3}개에 해당한다(한 가닥 기준).',
   f'종결 코돈을 빼면 아미노산은 {_aa}개이다.',
   f'아미노산 n개가 사슬로 연결되면 펩타이드 결합은 n − 1개이므로 {_bond}개이다.'])

_m = 'GGAUGCCAUGACUUAGCAUAA'
_r = orf(_m)
assert _r == ('MP', 2)
_second = orf(_m[5:])
assert _second[0] == 'MT'
q(T, 4, f"다음 mRNA가 번역될 때 합성되는 폴리펩타이드를 이루는 아미노산의 수는? (단, 번역은 5' 쪽의 첫 AUG에서 시작한다.)\n\nmRNA: 5'-{_m}-3'\n\n"
  f"{ctab(['AUG', 'CCA', 'UGA', 'CUU', 'AGC', 'AUA', 'ACU', 'UAG', 'UAA'])}",
  '2개', ['3개', '4개', '5개', '6개'],
  ['첫 AUG는 3~5번째 염기이다.',
   'AUG(메싸이오닌) CCA(프롤린) UGA(종결)이므로 아미노산 2개에서 번역이 끝난다.',
   '읽기 틀 안의 UGA를 놓치고 뒤쪽의 UAG나 UAA까지 읽으면 아미노산 수를 잘못 센다. 8~10번째 염기의 AUG는 다른 읽기 틀에 있어 이 번역과 관계없다.'])

_aa0 = 120
_A = 45 - 1
_B = _aa0 - 6 // 3
_C = _aa0 + 1 + 3
assert (_A, _B, _C) == (44, 118, 124)
HB(T, 5, f'정상 유전자 X로부터 아미노산 {_aa0}개로 된 폴리펩타이드가 합성된다. 돌연변이 (가)~(다)는 X의 번역 부위에 다음 변화가 각각 하나씩 일어난 것이다.\n\n'
   '(가) 45번째 코돈이 치환으로 종결 코돈이 되었다.\n'
   '(나) 번역 부위 중간에서 연속된 염기 6개(코돈 2개 분량)가 결실되었고, 새 종결 코돈은 생기지 않았다.\n'
   '(다) 원래의 종결 코돈이 치환으로 아미노산을 지정하는 코돈이 되었다. 원래 종결 코돈 뒤에는 같은 읽기 틀로 아미노산을 지정하는 코돈 3개가 있고, 그다음에 종결 코돈이 있다.\n\n'
   '이에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은?',
   [(f'(가)로부터 합성되는 폴리펩타이드는 아미노산 {_A}개로 이루어진다.', True,
     f'45번째 코돈에서 번역이 끝나므로 1~44번째 코돈의 아미노산 {_A}개이다'),
    (f'(나)로부터 합성되는 폴리펩타이드의 펩타이드 결합 수는 {_B - 1}개이다.', True,
     f'코돈 2개가 빠져도 읽기 틀이 유지되므로 아미노산 {_B}개, 펩타이드 결합 {_B - 1}개이다'),
    (f'(다)로부터 합성되는 폴리펩타이드는 아미노산 {_C - 1}개로 이루어진다.', False,
     f'원래 종결 코돈 자리의 아미노산 1개와 뒤쪽 코돈 3개의 아미노산이 추가되어 {_aa0} + 1 + 3 = {_C}개이다')],
   expect='ㄱ, ㄴ')

