# T9  u1m1s0t0  오페론 구조와 조절 원리 이해
# ═══════════════════════════════════════════════════════════
T = 'u1m1s0t0'
q(T, 1, '원핵생물의 오페론에 대한 설명으로 옳은 것은?',
  '하나의 프로모터에 의해 함께 전사가 조절되는 유전자 집단으로, 프로모터·작동 부위·구조 유전자로 이루어진다.',
  ['RNA 중합 효소가 결합하는 DNA 부위만을 가리킨다.', '억제 단백질을 암호화하는 유전자이다.',
   '진핵생물 유전자에서 인트론과 엑손으로 이루어진 단위이다.', '억제 단백질이 결합하는 DNA 부위만을 가리킨다.'],
  ['오페론은 기능이 관련된 여러 구조 유전자가 하나의 프로모터와 작동 부위의 조절을 받아 함께 전사되는 단위이다.',
   'RNA 중합 효소가 결합하는 곳은 프로모터, 억제 단백질이 결합하는 곳은 작동 부위이다.',
   '억제 단백질을 암호화하는 것은 조절 유전자로, 오페론 밖에 있다.'])

q(T, 2, '젖당 오페론과 관련된 DNA 부위와 그 기능을 옳게 짝지은 것은?',
  '작동 부위 – 억제 단백질이 결합하는 부위',
  ['프로모터 – 억제 단백질이 결합하는 부위', '조절 유전자 – 젖당 분해 효소를 암호화하는 부위',
   '구조 유전자 – RNA 중합 효소가 처음 결합하는 부위', '작동 부위 – 억제 단백질을 암호화하는 부위'],
  ['작동 부위는 억제 단백질이 결합하여 전사를 막는 스위치 역할을 한다.',
   '프로모터는 RNA 중합 효소가 결합하는 부위, 조절 유전자는 억제 단백질을 암호화하는 부위이다.',
   '구조 유전자는 젖당 분해 효소 등 젖당 이용에 필요한 단백질을 암호화한다.'])

q(T, 3, '대장균의 젖당 오페론과 조절 유전자에 대한 설명으로 옳은 것은?',
  '조절 유전자는 젖당 오페론에 포함되지 않으며, 자신의 프로모터를 가지고 따로 전사된다.',
  ['조절 유전자는 젖당이 있을 때만 전사된다.',
   '젖당 오페론의 구조 유전자들은 각각 다른 프로모터에서 따로 전사된다.',
   '억제 단백질은 구조 유전자의 한가운데에 결합하여 번역을 막는다.',
   '젖당 오페론의 프로모터는 억제 단백질을 암호화한다.'],
  ['조절 유전자는 오페론 앞쪽에 따로 있으며, 자신의 프로모터를 이용해 젖당 유무와 관계없이 늘 전사되어 억제 단백질을 만든다.',
   '젖당 오페론의 구조 유전자들은 하나의 프로모터에서 하나의 mRNA로 함께 전사된다.',
   '억제 단백질은 작동 부위에 결합하여 전사를 억제하며, 프로모터는 단백질을 암호화하지 않는 조절 부위이다.'])

q(T, 3, '오페론을 통한 원핵생물의 유전자 발현 조절에 대한 설명으로 옳지 «않은» 것은?',
  '진핵생물의 유전자들도 대부분 오페론을 이루어 하나의 mRNA로 함께 전사된다.',
  ['기능이 관련된 여러 유전자의 발현을 한꺼번에 조절할 수 있다.',
   '필요할 때만 효소를 만들어 물질과 에너지의 낭비를 줄인다.',
   '억제 단백질이 작동 부위에 결합하면 구조 유전자가 전사되지 않는다.',
   '환경 변화에 따라 필요한 유전자의 전사를 빠르게 조절할 수 있다.'],
  ['진핵생물의 유전자는 대부분 유전자마다 각각의 프로모터를 가지고 따로 전사되며, 여러 전사 인자의 조합으로 조절된다.',
   '오페론은 관련 유전자를 한꺼번에 켜고 끌 수 있어, 원핵생물이 환경 변화에 빠르게 대응하고 낭비를 줄이게 한다.',
   '억제 단백질이 작동 부위에 결합해 있으면 RNA 중합 효소가 구조 유전자를 전사하지 못한다.'])

_parts = ['(라)', '(가)', '(나)', '(다)']
_ok = ' – '.join(_parts)
_ch = [_ok, '(가) – (라) – (나) – (다)', '(라) – (나) – (가) – (다)', '(가) – (나) – (다) – (라)', '(라) – (가) – (다) – (나)']
assert len(set(_ch)) == 5
_ch = _ch[1:4] + [_ok] + _ch[4:]
qf(T, 4, '다음은 대장균의 젖당 오페론과 그 주변 DNA 부위 (가)~(라)의 특징이다.\n\n'
   '(가) RNA 중합 효소가 결합하여 오페론의 전사가 시작되는 부위\n'
   '(나) 억제 단백질이 결합하는 부위\n'
   '(다) 젖당 분해 효소 등을 암호화하는 부위\n'
   '(라) 억제 단백질을 암호화하며 젖당 오페론 밖에 있는 부위\n\n'
   '젖당 오페론의 전사 방향을 기준으로 앞쪽(상류)부터 (가)~(라)를 순서대로 옳게 배열한 것은?',
   _ch, 3,
   ['(가)는 프로모터, (나)는 작동 부위, (다)는 구조 유전자, (라)는 조절 유전자이다.',
    '조절 유전자는 오페론 앞쪽에 따로 있고, 오페론은 프로모터 → 작동 부위 → 구조 유전자 순으로 배열된다.',
    'RNA 중합 효소는 프로모터에 결합한 뒤 작동 부위를 지나 구조 유전자를 전사하므로, 작동 부위에 억제 단백질이 붙어 있으면 전사가 막힌다.'])

HB(T, 5, '대장균의 젖당 오페론에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은?',
   [('조절 유전자는 젖당 오페론을 구성하는 부위 중 하나이다.', False,
     '젖당 오페론은 프로모터, 작동 부위, 구조 유전자로 이루어지며, 조절 유전자는 오페론 밖에 있다'),
    ('젖당 오페론의 구조 유전자들은 하나의 mRNA로 함께 전사된다.', True,
     '구조 유전자들은 하나의 프로모터를 공유하므로 하나의 mRNA로 함께 전사된다'),
    ('조절 유전자에 돌연변이가 일어나 억제 단백질이 작동 부위에 결합하지 못하게 되면, 젖당이 없어도 구조 유전자가 전사된다.', True,
     '작동 부위를 막을 억제 단백질이 없으므로 젖당 유무와 관계없이 전사된다')],
   expect='ㄴ, ㄷ')

