T = 'u1m1s0t1'
q(T, 1, '포도당은 없고 젖당이 있는 배지에서 대장균의 젖당 오페론 구조 유전자가 전사되는 까닭으로 옳은 것은?',
  '젖당 유도체가 억제 단백질에 결합하여, 억제 단백질이 작동 부위에 결합하지 못하기 때문이다.',
  ['젖당이 RNA 중합 효소를 분해하기 때문이다.', '젖당이 있으면 조절 유전자가 결실되기 때문이다.',
   '젖당 유도체가 작동 부위에 결합하여 RNA 중합 효소를 끌어오기 때문이다.', '젖당이 구조 유전자의 인트론을 제거하기 때문이다.'],
  ['젖당이 들어오면 젖당 유도체가 억제 단백질에 결합하여 억제 단백질의 구조를 바꾼다.',
   '구조가 바뀐 억제 단백질은 작동 부위에 결합하지 못하므로 RNA 중합 효소가 구조 유전자를 전사한다.',
   '젖당 유도체는 작동 부위가 아니라 억제 단백질에 결합한다. 원핵생물 유전자에는 대개 인트론이 없다.'])

q(T, 2, '야생형 대장균에서 젖당 오페론 구조 유전자의 발현이 가장 활발하게 일어나는 배지 조건은?',
  '포도당은 없고 젖당만 있는 배지',
  ['포도당과 젖당이 모두 없는 배지', '포도당만 있고 젖당은 없는 배지', '포도당과 젖당이 모두 있는 배지', '젖당은 없고 아미노산만 있는 배지'],
  ['젖당이 있어야 젖당 유도체가 억제 단백질을 떼어 내므로 구조 유전자가 전사될 수 있다.',
   '대장균은 포도당이 있으면 포도당을 먼저 이용하므로, 포도당이 함께 있을 때는 젖당 오페론의 발현이 활발하지 않다.',
   '따라서 포도당은 없고 젖당만 있을 때 발현이 가장 활발하다. 젖당이 없는 배지에서는 억제 단백질이 작동 부위를 막는다.'])

q(T, 3, '포도당과 젖당이 모두 없는 배지에서 야생형 대장균의 상태를 옳게 나타낸 것은?',
  '조절 유전자 전사: 일어남 / 억제 단백질의 작동 부위 결합: 일어남 / 구조 유전자 전사: 일어나지 않음',
  ['조절 유전자 전사: 일어나지 않음 / 억제 단백질의 작동 부위 결합: 일어나지 않음 / 구조 유전자 전사: 일어남',
   '조절 유전자 전사: 일어나지 않음 / 억제 단백질의 작동 부위 결합: 일어남 / 구조 유전자 전사: 일어나지 않음',
   '조절 유전자 전사: 일어남 / 억제 단백질의 작동 부위 결합: 일어나지 않음 / 구조 유전자 전사: 일어남',
   '조절 유전자 전사: 일어남 / 억제 단백질의 작동 부위 결합: 일어남 / 구조 유전자 전사: 일어남'],
  ['조절 유전자는 젖당 유무와 관계없이 늘 전사되어 억제 단백질을 만든다.',
   '젖당이 없으면 억제 단백질이 작동 부위에 결합하므로 구조 유전자가 전사되지 않는다.',
   '조절 유전자가 전사되지 않는다고 본 선택지는 조절 유전자의 발현이 늘 일어난다는 점을 놓친 것이다.'])

q(T, 3, '포도당은 없고 젖당이 있는 배지에서 배양한 야생형 대장균에 대한 설명으로 옳지 «않은» 것은?',
  '억제 단백질이 만들어지지 않는다.',
  ['젖당 유도체와 억제 단백질이 결합한다.', 'RNA 중합 효소가 젖당 오페론의 구조 유전자를 전사한다.',
   '젖당 분해 효소가 합성된다.', '조절 유전자가 전사된다.'],
  ['조절 유전자는 늘 발현되므로 젖당이 있어도 억제 단백질은 만들어진다. 다만 젖당 유도체와 결합하여 작동 부위에 붙지 못할 뿐이다.',
   '그 결과 RNA 중합 효소가 구조 유전자를 전사하고 젖당 분해 효소가 합성된다.',
   '따라서 억제 단백질이 만들어지지 않는다는 설명이 틀렸다.'])

q(T, 4, '야생형 대장균을 포도당과 젖당이 모두 없는 배지에서 배양하다가(구간 Ⅰ), 포도당은 없고 젖당만 있는 배지로 옮겨 배양하였다(구간 Ⅱ). 시간이 지나 배지의 젖당이 모두 분해된 뒤에도 계속 배양하였다(구간 Ⅲ). 표는 각 구간에서 측정한 mRNA의 양을 상댓값으로 나타낸 것이다.\n\n'
  '| 구간 | 젖당 오페론 구조 유전자의 mRNA | 억제 단백질의 mRNA |\n| Ⅰ | 0.1 | 1 |\n| Ⅱ | 10 | 1 |\n| Ⅲ | 0.1 | 1 |\n\n'
  '이에 대한 설명으로 옳은 것은?',
  '구간 Ⅲ에서는 젖당 유도체가 없어져 억제 단백질이 다시 작동 부위에 결합하였다.',
  ['구간 Ⅰ에서는 억제 단백질이 만들어지지 않았다.', '구간 Ⅱ에서는 억제 단백질 유전자의 전사가 멈추었다.',
   '구간 Ⅱ에서 젖당 유도체는 프로모터에 결합하여 전사를 촉진하였다.', '젖당 분해 효소는 구간 Ⅰ과 Ⅲ에서 가장 많이 합성되었다.'],
  ['억제 단백질의 mRNA는 모든 구간에서 1로 일정하다. 조절 유전자는 늘 전사되며, 구간 Ⅰ에서도 억제 단백질이 만들어졌다.',
   '구간 Ⅱ에서 젖당 유도체가 억제 단백질에 결합하여 억제가 풀리므로 구조 유전자 mRNA가 10으로 늘었다(젖당 분해 효소도 이때 많이 합성).',
   '구간 Ⅲ에서 젖당이 모두 분해되면 억제 단백질이 다시 작동 부위에 결합하여 구조 유전자 mRNA가 0.1로 줄었다.'])

HB(T, 5, '야생형 대장균을 배지 Ⅰ(포도당 없음, 젖당 없음)과 배지 Ⅱ(포도당 없음, 젖당 있음)에서 각각 배양하였다. 이에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은?',
   [('Ⅰ에서 RNA 중합 효소는 조절 유전자를 전사하지 않는다.', False,
     '조절 유전자는 젖당 유무와 관계없이 늘 전사된다'),
    ('Ⅱ에서 전사된 젖당 오페론의 mRNA에는 억제 단백질을 암호화하는 부위가 포함되어 있다.', False,
     '억제 단백질은 오페론 밖의 조절 유전자가 암호화하므로 젖당 오페론의 mRNA에는 포함되지 않는다'),
    ('Ⅱ에서 억제 단백질은 존재하지만 작동 부위에 결합하지 못한다.', True,
     '억제 단백질은 만들어지지만 젖당 유도체와 결합하여 구조가 바뀌어 작동 부위에 결합하지 못한다')],
   expect='ㄷ')

# ── 젖당 오페론 모형(돌연변이 판정용) ─────────────────────
def lac(mut, lactose):
    """→ (구조 유전자 전사 여부, 억제 단백질 존재 여부, 억제 단백질의 작동 부위 결합 여부)"""
    rep = mut != '조절 유전자 결실'
    inducible = mut != '억제 단백질이 젖당 유도체와 결합 못함'
    op_ok = mut != '작동 부위 결실'
    bound = rep and op_ok and (not lactose or not inducible) and mut != '억제 단백질이 DNA에 결합 못함'
    prom = mut != '프로모터 결실'
    return (prom and not bound, rep, bound)


assert lac('야생형', False) == (False, True, True) and lac('야생형', True) == (True, True, False)

# ═══════════════════════════════════════════════════════════
