q(T, 1, '조절 유전자가 결실되어 억제 단백질을 만들지 못하는 돌연변이 대장균을 포도당과 젖당이 모두 없는 배지에서 배양하였다. 이 대장균에 대한 설명으로 옳은 것은?',
  '젖당이 없어도 젖당 오페론의 구조 유전자가 전사된다.',
  ['억제 단백질이 작동 부위에 결합하여 전사가 억제된다.', 'RNA 중합 효소가 프로모터에 결합하지 못한다.',
   '젖당 유도체가 억제 단백질에 결합한다.', '조절 유전자로부터 정상 억제 단백질이 만들어진다.'],
  ['억제 단백질이 없으므로 작동 부위가 늘 비어 있다.',
   '따라서 젖당이 없어도 RNA 중합 효소가 구조 유전자를 전사한다(구조 유전자가 늘 발현됨).',
   '젖당이 없는 배지이므로 젖당 유도체도 없고, 결합할 억제 단백질도 없다.'])

assert lac('프로모터 결실', True)[0] is False
q(T, 2, '젖당 오페론의 프로모터가 결실된 돌연변이 대장균을 포도당은 없고 젖당이 있는 배지에서 배양하였다. 이때 나타나는 결과로 옳은 것은?',
  'RNA 중합 효소가 결합하지 못하여 구조 유전자가 전사되지 않는다.',
  ['억제 단백질이 없어 구조 유전자가 더 많이 전사된다.', '젖당 유도체가 작동 부위에 결합하여 전사가 일어난다.',
   '조절 유전자가 전사되지 않아 억제 단백질이 만들어지지 않는다.', '구조 유전자가 전사되지만 번역되지 않는다.'],
  ['프로모터는 RNA 중합 효소가 결합하는 부위이므로, 결실되면 젖당이 있어도 구조 유전자가 전사되지 않는다.',
   '조절 유전자는 자신의 프로모터를 따로 가지므로 억제 단백질은 정상적으로 만들어진다.',
   '젖당 유도체는 작동 부위가 아니라 억제 단백질에 결합한다.'])

_wt = [lac('야생형', L)[0] for L in (False, True)]
_c = {m: [lac(m, L)[0] for L in (False, True)] for m in ['작동 부위 결실', '프로모터 결실', '억제 단백질이 젖당 유도체와 결합 못함']}
assert _wt == [False, True] and _c['작동 부위 결실'] == [True, True] and _c['프로모터 결실'] == [False, False] and _c['억제 단백질이 젖당 유도체와 결합 못함'] == [False, False]
q(T, 3, '표는 야생형 대장균과 돌연변이 대장균 Ⅰ을 두 배지에서 배양했을 때 젖당 분해 효소의 합성 여부를 나타낸 것이다. (O: 합성됨, X: 합성 안 됨)\n\n'
  '| 균주 | 포도당 없음·젖당 없음 | 포도당 없음·젖당 있음 |\n| 야생형 | X | O |\n| Ⅰ | O | O |\n\n'
  'Ⅰ에 해당할 수 있는 돌연변이로 가장 적절한 것은?',
  '작동 부위의 염기 서열이 바뀌어 억제 단백질이 결합하지 못하는 돌연변이',
  ['젖당 오페론의 프로모터가 결실된 돌연변이', '억제 단백질이 젖당 유도체와 결합하지 못하는 돌연변이',
   '젖당 분해 효소 유전자가 결실된 돌연변이', '억제 단백질이 작동 부위에 더 단단히 결합하도록 바뀐 돌연변이'],
  ['Ⅰ은 젖당이 없어도 효소를 만든다. 억제 단백질이 작동 부위를 막지 못하는 경우이다.',
   '작동 부위가 바뀌어 억제 단백질이 결합하지 못하면 젖당 유무와 관계없이 전사된다.',
   '프로모터 결실·억제 단백질이 젖당 유도체와 결합 못함·효소 유전자 결실은 모두 젖당이 있어도 효소가 합성되지 않고, 억제 단백질이 더 단단히 결합하면 젖당이 없을 때 합성될 수 없다.'])

assert lac('작동 부위 결실', False)[1] is True
q(T, 3, '젖당 오페론의 돌연변이에 대한 설명으로 옳지 «않은» 것은?',
  '작동 부위가 결실된 돌연변이는 억제 단백질을 만들지 못한다.',
  ['작동 부위가 결실된 돌연변이는 젖당이 없어도 구조 유전자가 전사된다.',
   '조절 유전자가 결실된 돌연변이는 젖당이 없어도 구조 유전자가 전사된다.',
   '억제 단백질이 젖당 유도체와 결합하지 못하는 돌연변이는 젖당이 있어도 구조 유전자가 전사되지 않는다.',
   '프로모터가 결실된 돌연변이는 젖당 유무와 관계없이 구조 유전자가 전사되지 않는다.'],
  ['억제 단백질은 조절 유전자가 만든다. 작동 부위가 결실되어도 조절 유전자는 정상이므로 억제 단백질은 만들어진다(결합할 자리만 없음).',
   '작동 부위 결실·조절 유전자 결실은 젖당이 없어도 전사가 일어난다.',
   '억제 단백질이 젖당 유도체와 결합하지 못하면 작동 부위에서 떨어지지 않아 늘 억제되고, 프로모터가 없으면 늘 전사되지 않는다.'])

_muts = ['작동 부위 결실', '프로모터 결실', '조절 유전자 결실']
_true_map = {'A': '작동 부위 결실', 'B': '프로모터 결실', 'C': '조절 유전자 결실'}
_obs = {k: [lac(v, L)[:2] for L in (False, True)] for k, v in _true_map.items()}
_ok_perms = [p for p in itertools.permutations(_muts) if all([lac(m, L)[:2] for L in (False, True)] == _obs[k] for k, m in zip('ABC', p))]
assert _ok_perms == [tuple(_true_map[k] for k in 'ABC')]
_OX = lambda b: 'O' if b else 'X'
_rows = '\n'.join(f'| {k} | ' + ' | '.join(f'{_OX(a)} | {_OX(b)}' for a, b in _obs[k]) + ' |' for k in 'ABC')
_all = [', '.join(f'{k}: {m}' for k, m in zip('ABC', p)) for p in itertools.permutations(_muts)]
_ans = ', '.join(f'{k}: {_true_map[k]}' for k in 'ABC')
_wr = [x for x in _all if x != _ans][:4]
q(T, 4, '대장균 A~C는 각각 젖당 오페론의 작동 부위 결실, 젖당 오페론의 프로모터 결실, 조절 유전자 결실 돌연변이 중 하나이다. 표는 포도당이 없는 배지에서 젖당의 유무에 따라 구조 유전자의 전사 여부와 억제 단백질의 존재 여부를 조사한 것이다. (O: 있음/일어남, X: 없음/일어나지 않음)\n\n'
  '| 균주 | 젖당 없음: 구조 유전자 전사 | 젖당 없음: 억제 단백질 | 젖당 있음: 구조 유전자 전사 | 젖당 있음: 억제 단백질 |\n' + _rows +
  '\n\nA~C의 돌연변이를 옳게 짝지은 것은?',
  _ans, _wr,
  ['억제 단백질이 없는 C는 조절 유전자 결실이다(억제 단백질이 없으니 늘 전사).',
   '억제 단백질은 있는데 젖당이 없어도 전사되는 A는 작동 부위 결실이다(억제 단백질이 결합할 자리가 없음).',
   '억제 단백질이 있고 젖당이 있어도 전사되지 않는 B는 프로모터 결실이다.'])

_true = {'(가)': '억제 단백질이 젖당 유도체와 결합 못함', '(나)': '야생형', '(다)': '조절 유전자 결실'}
_enz = {k: [lac(v, L)[0] for L in (False, True)] for k, v in _true.items()}
_rp = {k: lac(v, False)[1] for k, v in _true.items()}
assert _enz['(가)'] == [False, False] and _enz['(나)'] == [False, True] and _enz['(다)'] == [True, True]
assert _rp == {'(가)': True, '(나)': True, '(다)': False}
assert lac(_true['(가)'], True)[2] is True
_cands = ['야생형', '조절 유전자 결실', '억제 단백질이 젖당 유도체와 결합 못함']
_fits = [p for p in itertools.permutations(_cands) if all([lac(m, L)[0] for L in (False, True)] == _enz[k] for k, m in zip(['(가)', '(나)', '(다)'], p))]
assert len(_fits) == 1
HB(T, 5, '대장균 (가)~(다)는 야생형, 조절 유전자 결실 돌연변이, 억제 단백질이 젖당 유도체와 결합하지 못하는 돌연변이를 순서 없이 나타낸 것이다. 표는 포도당이 없는 배지에서 젖당 유무에 따른 젖당 분해 효소의 합성 여부와 억제 단백질의 존재 여부를 나타낸 것이다. (O: 있음/합성됨, X: 없음/합성 안 됨)\n\n'
   '| 균주 | 젖당 없음: 효소 합성 | 젖당 있음: 효소 합성 | 억제 단백질 |\n| (가) | X | X | ㉠ |\n| (나) | X | O | O |\n| (다) | O | ㉡ | X |\n\n'
   '이에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은?',
   [('(가)는 억제 단백질이 젖당 유도체와 결합하지 못하는 돌연변이이다.', True,
     '젖당이 있어도 효소가 합성되지 않는 것은 억제 단백질이 젖당 유도체와 결합하지 못해 작동 부위에서 떨어지지 않는 경우이다. (나)는 야생형, 억제 단백질이 없는 (다)는 조절 유전자 결실이다'),
    ('㉠과 ㉡은 모두 O이다.', True,
     '(가)의 조절 유전자는 정상이므로 억제 단백질이 있고(㉠ = O), (다)는 억제 단백질이 없어 젖당이 있어도 효소가 합성된다(㉡ = O)'),
    ('젖당이 있는 배지에서 (가)의 억제 단백질은 작동 부위에 결합해 있다.', True,
     '(가)의 억제 단백질은 젖당 유도체와 결합하지 못하므로 젖당이 있어도 작동 부위에 계속 결합해 있다')],
   expect='ㄱ, ㄴ, ㄷ')

