# T13  u1m1s1t0  진핵생물 발현 조절 단계 구분
# ═══════════════════════════════════════════════════════════
T = 'u1m1s1t0'
q(T, 1, '진핵생물의 유전자 발현 조절 중 전사 후 조절(RNA 가공 단계)에 해당하는 것은?',
  '1차 전사체에서 엑손을 선택적으로 연결하여 서로 다른 mRNA를 만든다.',
  ['응축된 염색질이 느슨하게 풀려 RNA 중합 효소가 접근할 수 있게 된다.', '전사 인자가 프로모터 근처의 조절 부위에 결합한다.',
   '합성된 폴리펩타이드의 일부가 잘려 나가 활성을 가진 단백질이 된다.', 'DNA 복제 중 생긴 잘못된 염기쌍을 수선한다.'],
  ['선택적 RNA 스플라이싱은 전사가 끝난 뒤 RNA 가공 단계에서 일어나는 조절이다.',
   '염색질이 풀리는 것은 전사 개시 전(염색질 구조) 조절, 전사 인자 결합은 전사 단계 조절이다.',
   '폴리펩타이드가 잘려 활성화되는 것은 번역 후 조절이고, DNA 수선은 유전자 발현 조절이 아니다.'])

q(T, 2, '어떤 진핵세포에서 유전자 X가 있는 부위의 염색질은 매우 응축되어 있어 RNA 중합 효소와 전사 인자가 X의 프로모터에 접근하지 못한다. 이와 같이 X의 발현이 조절되는 단계는?',
  '전사 개시 전 단계(염색질 구조의 조절)', ['번역 단계', '번역 후 단계', 'RNA 가공 단계', 'mRNA 분해 단계'],
  ['진핵생물의 DNA는 히스톤 단백질에 감겨 염색질을 이루며, 응축 정도에 따라 전사 가능성이 달라진다.',
   '염색질이 응축되어 전사 관련 단백질이 접근하지 못하는 것은 전사가 시작되기 전 단계의 조절이다.',
   'RNA 가공·mRNA 분해·번역·번역 후 조절은 모두 전사가 일어난 뒤의 단계이다.'])

_ok = '(다) → (가) → (마) → (나) → (라)'
_ch = [_ok, '(가) → (다) → (마) → (나) → (라)', '(다) → (가) → (나) → (마) → (라)', '(다) → (마) → (가) → (나) → (라)', '(가) → (마) → (다) → (라) → (나)']
assert len(set(_ch)) == 5
_ch = [_ch[1], _ok] + _ch[2:]
qf(T, 3, '다음은 진핵세포에서 유전자 발현이 조절될 수 있는 단계 (가)~(마)를 순서 없이 나타낸 것이다.\n\n'
   '(가) 전사 인자와 RNA 중합 효소가 결합하여 전사가 시작된다.\n'
   '(나) 성숙한 mRNA가 핵공을 통해 세포질로 이동하여 리보솜에서 번역된다.\n'
   '(다) 응축된 염색질이 느슨하게 풀린다.\n'
   '(라) 폴리펩타이드가 접히거나 일부가 잘리는 등 가공되어 기능을 가진 단백질이 된다.\n'
   '(마) 1차 전사체에서 인트론이 제거되고 모자 구조와 폴리 A 꼬리가 첨가된다.\n\n'
   '유전자 발현 과정의 순서대로 옳게 나열한 것은?',
   _ch, 1,
   ['염색질이 풀려야(다) 전사가 시작될 수 있고(가), 1차 전사체는 핵 안에서 가공된다(마).',
    '가공된 mRNA가 세포질로 나가 번역되고(나), 번역된 폴리펩타이드가 가공되어 기능을 갖는다(라).',
    '진핵생물은 이 모든 단계에서 유전자 발현을 조절할 수 있다.'])

q(T, 3, '진핵생물의 유전자 발현 조절에 대한 설명으로 옳지 «않은» 것은?',
  '진핵생물의 유전자 발현은 전사 단계에서만 조절된다.',
  ['핵막이 있어 전사와 번역이 서로 다른 장소에서 일어난다.',
   'RNA 중합 효소는 전사 인자의 도움을 받아 프로모터에 결합한다.',
   '여러 전사 인자의 조합에 따라 유전자의 전사 여부가 달라진다.',
   'mRNA가 분해되는 속도에 따라 합성되는 단백질의 양이 달라질 수 있다.'],
  ['진핵생물은 염색질 구조, 전사, RNA 가공, mRNA 수송·분해, 번역, 번역 후 단계 등 여러 단계에서 발현을 조절한다.',
   '전사는 핵, 번역은 세포질에서 일어나며, RNA 중합 효소는 전사 인자와 함께 전사 개시 복합체를 이룬다.',
   'mRNA가 오래 남아 있으면 더 많이 번역된다.'])

_cells = {'Ⅰ': ('O', 'O', 'O', 'O'), 'Ⅱ': ('X', 'X', 'X', 'X'), 'Ⅲ': ('O', 'X', 'X', 'X'), 'Ⅳ': ('O', 'O', 'X', 'X')}
_stage = {}
for k, (pre, mat, ribo, prot) in _cells.items():
    _stage[k] = '발현됨' if prot == 'O' else ('전사' if pre == 'X' else ('전사 후(RNA 가공·수송)' if mat == 'X' else '번역'))
assert _stage == {'Ⅰ': '발현됨', 'Ⅱ': '전사', 'Ⅲ': '전사 후(RNA 가공·수송)', 'Ⅳ': '번역'}
_ans = f"Ⅱ: {_stage['Ⅱ']}, Ⅲ: {_stage['Ⅲ']}, Ⅳ: {_stage['Ⅳ']}"
q(T, 4, '표는 어떤 사람의 세포 Ⅰ~Ⅳ에서 유전자 G와 관련된 물질의 존재 여부를 조사한 것이다. (O: 있음, X: 없음)\n\n'
  '| 세포 | 핵 속 G의 1차 전사체 | 세포질의 G 성숙한 mRNA | 리보솜에 결합한 G mRNA | G 단백질 |\n' +
  '\n'.join(f'| {k} | ' + ' | '.join(v) + ' |' for k, v in _cells.items()) +
  '\n\nⅡ~Ⅳ에서 G의 발현이 조절되어 G 단백질이 만들어지지 않은 단계를 옳게 짝지은 것은?',
  _ans,
  ['Ⅱ: 번역, Ⅲ: 전사, Ⅳ: 전사 후(RNA 가공·수송)', 'Ⅱ: 전사, Ⅲ: 번역, Ⅳ: 전사 후(RNA 가공·수송)',
   'Ⅱ: 전사 후(RNA 가공·수송), Ⅲ: 전사, Ⅳ: 번역', 'Ⅱ: 전사, Ⅲ: 전사 후(RNA 가공·수송), Ⅳ: 번역 후'],
  ['Ⅱ는 1차 전사체부터 없으므로 전사 단계에서 발현이 막혔다.',
   'Ⅲ은 1차 전사체는 있지만 세포질에 성숙한 mRNA가 없으므로 RNA 가공이나 핵 밖 수송 단계에서 막혔다.',
   'Ⅳ는 세포질에 mRNA가 있지만 리보솜에 결합하지 못했으므로 번역 단계에서 막혔다. (번역 후 조절이라면 리보솜에 결합한 mRNA가 있어야 한다.)'])

HB(T, 5, '진핵생물의 유전자 발현 조절에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은?',
   [('염색질이 응축된 부위에 있는 유전자일수록 전사가 활발하게 일어난다.', False,
     '응축된 염색질에서는 RNA 중합 효소와 전사 인자가 DNA에 접근하기 어려워 전사가 잘 일어나지 않는다'),
    ('합성된 폴리펩타이드의 일부가 잘려 나가 활성을 갖게 되는 것은 번역 후 조절에 해당한다.', True,
     '번역이 끝난 뒤 단백질이 가공·변형되는 단계의 조절이다'),
    ('세포질에서 mRNA가 빨리 분해되면 그 mRNA로부터 합성되는 단백질의 양이 줄어든다.', True,
     'mRNA가 번역될 수 있는 시간이 짧아지므로 단백질 합성량이 줄어든다(전사 후 조절)')],
   expect='ㄴ, ㄷ')

