# ═══════════════════════════════════════════════════════════
T = 'u1m1s1t1'
q(T, 1, '진핵생물의 전사 인자에 대한 설명으로 옳은 것은?',
  'DNA의 특정 조절 부위나 RNA 중합 효소에 결합하여 전사를 조절하는 단백질이다.',
  ['RNA를 주형으로 DNA를 합성하는 효소이다.', 'mRNA의 코돈을 인식하여 아미노산을 운반하는 RNA이다.',
   '끊어진 DNA 조각을 연결하는 효소이다.', '1차 전사체에서 엑손을 잘라 내는 RNA이다.'],
  ['전사 인자는 조절 부위 등에 결합하여 RNA 중합 효소가 전사를 시작하도록 돕거나 억제하는 단백질이다.',
   'RNA를 주형으로 DNA를 합성하는 것은 역전사 효소, 아미노산을 운반하는 것은 tRNA, DNA 조각을 잇는 것은 DNA 연결 효소이다.',
   'RNA 가공에서는 엑손이 아니라 인트론이 제거된다.'])

q(T, 2, '진핵세포의 염색질 구조와 전사의 관계에 대한 설명으로 옳은 것은?',
  'DNA가 히스톤 단백질에 단단히 감겨 응축된 부위에서는 전사가 잘 일어나지 않는다.',
  ['염색질이 응축될수록 RNA 중합 효소가 DNA에 더 쉽게 결합한다.', '염색질 구조는 모든 세포에서 같으므로 전사에 영향을 주지 않는다.',
   '히스톤 단백질은 RNA로 이루어져 있다.', '염색질이 풀리면 유전자의 염기 서열이 바뀌어 전사가 일어난다.'],
  ['DNA는 히스톤 단백질을 감아 뉴클레오솜을 이루고, 이것이 응축되어 염색질을 형성한다.',
   '응축된 부위는 전사 인자와 RNA 중합 효소가 접근하기 어려워 전사가 억제되고, 느슨하게 풀린 부위에서는 전사가 일어나기 쉽다.',
   '염색질 구조의 변화는 염기 서열을 바꾸지 않으며, 세포 종류에 따라 풀려 있는 부위가 다르다.'])

q(T, 3, '진핵생물의 전사 조절 부위와 전사 인자에 대한 설명으로 옳은 것은?',
  '프로모터에서 멀리 떨어진 원거리 조절 부위에 결합한 전사 인자도 DNA가 구부러지면 전사 개시 복합체에 작용할 수 있다.',
  ['원거리 조절 부위는 항상 프로모터 바로 옆에 붙어 있다.', '진핵생물의 RNA 중합 효소는 전사 인자 없이 단독으로 프로모터에 결합한다.',
   '하나의 유전자의 전사에는 한 종류의 전사 인자만 관여한다.', '전사 인자는 mRNA에 결합하여 번역을 시작하게 한다.'],
  ['진핵생물 유전자에는 프로모터 가까이의 근거리 조절 부위와 멀리 떨어진 원거리 조절 부위가 있다.',
   '원거리 조절 부위에 결합한 전사 인자(활성자)는 DNA가 휘어지면서 프로모터 쪽의 전사 개시 복합체와 상호 작용하여 전사를 촉진한다.',
   'RNA 중합 효소는 여러 전사 인자의 도움을 받아야 프로모터에 결합하며, 한 유전자의 전사에 여러 전사 인자가 함께 관여한다.'])

q(T, 3, '진핵생물의 전사 인자에 대한 설명으로 옳지 «않은» 것은?',
  '모든 세포에서 같은 종류의 전사 인자가 같은 양으로 만들어진다.',
  ['전사 인자는 단백질이며, 전사 인자 자신도 유전자로부터 발현되어 만들어진다.',
   '어떤 전사 인자는 RNA 중합 효소가 프로모터에 결합하는 데 필요하다.',
   '전사를 억제하는 작용을 하는 전사 인자도 있다.',
   '하나의 전사 인자가 여러 유전자의 전사를 함께 조절할 수 있다.'],
  ['세포 종류마다 만들어지는 전사 인자의 종류와 양이 달라서, 같은 유전체를 가져도 서로 다른 유전자가 발현된다.',
   '전사 인자도 유전자의 산물(단백질)이다. RNA 중합 효소의 결합을 돕는 전사 인자, 전사를 촉진하거나 억제하는 전사 인자가 있다.',
   '같은 조절 부위를 가진 여러 유전자는 한 전사 인자에 의해 함께 조절될 수 있다.'])

_cons = {'Ⅰ': ('a, b, c', 100), 'Ⅱ': ('b, c', 100), 'Ⅲ': ('a, c', 5), 'Ⅳ': ('a, b', 100), 'Ⅴ': ('없음', 5)}
_need = [s for s in 'abc' if any(v[1] < 50 and s not in v[0] and v[0] != '없음' for v in _cons.values())]
assert _need == ['b']
q(T, 4, '유전자 G의 앞쪽에는 전사 조절 부위 a, b, c가 있다. 간세포에 조절 부위 일부를 없앤 G를 각각 넣고 G의 발현량을 측정하였다.\n\n'
  '| 구성 | 남아 있는 조절 부위 | G의 발현량(상댓값) |\n' + '\n'.join(f'| {k} | {v[0]} | {v[1]} |' for k, v in _cons.items()) +
  '\n\n이 결과에 대한 해석으로 가장 적절한 것은? (단, 프로모터는 모든 구성에 있다.)',
  '간세포에서 G가 높은 수준으로 발현되려면 조절 부위 b가 필요하다.',
  ['a가 없으면 G가 거의 발현되지 않는다.', '간세포에서 c에 결합하는 전사 인자는 G의 발현에 반드시 필요하다.',
   '조절 부위가 모두 없어도 발현량은 변하지 않는다.', 'b는 G의 발현을 억제하는 조절 부위이다.'],
  ['b만 없앤 Ⅲ에서 발현량이 5로 크게 줄었고, a나 c를 없앤 Ⅱ·Ⅳ는 100으로 그대로이다.',
   '따라서 간세포에서 G의 높은 발현에는 b(와 b에 결합하는 전사 인자)가 필요하고, a와 c는 없어도 된다.',
   'b가 억제 부위라면 b를 없앨 때 발현량이 늘어야 하는데 오히려 줄었다. 조절 부위가 모두 없는 Ⅴ도 5로 줄었다.'])

_expr = {'무처리': 10, 'A 처리': 50, 'B 처리': 1}
assert _expr['A 처리'] > _expr['무처리'] > _expr['B 처리']
HB(T, 5, '물질 A를 처리하면 세포의 염색질이 느슨하게 풀리고, 물질 B를 처리하면 염색질이 더 응축된다. 표는 어떤 세포에 A 또는 B를 처리한 뒤 유전자 G의 mRNA 양을 측정한 결과이다. (A와 B는 DNA의 염기 서열을 바꾸지 않는다.)\n\n'
   '| 처리 | G의 mRNA 양(상댓값) |\n' + '\n'.join(f'| {k} | {v} |' for k, v in _expr.items()) +
   '\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은?',
   [('염색질이 느슨하게 풀리면 G의 전사가 촉진된다.', True,
     'A 처리로 염색질이 풀리자 mRNA 양이 10에서 50으로 늘었다'),
    ('B 처리 시 G의 발현이 줄어든 것은 번역 단계에서 조절된 결과이다.', False,
     'B 처리로 mRNA 양 자체가 줄었으므로, 염색질 응축으로 전사가 억제된 것이다(번역 단계가 아니다)'),
    ('염색질 구조의 변화는 DNA 염기 서열의 변화 없이도 유전자 발현량을 바꿀 수 있다.', True,
     'A, B는 염기 서열을 바꾸지 않는데도 G의 mRNA 양이 달라졌다')],
   expect='ㄱ, ㄷ')

# ═══════════════════════════════════════════════════════════
# T15  u1m1s1t2  세포 분화와 선택적 유전자 발현 분석
# ═══════════════════════════════════════════════════════════
T = 'u1m1s1t2'
q(T, 1, '다세포 생물의 세포 분화에 대한 설명으로 옳은 것은?',
  '같은 유전체를 가진 세포들이 서로 다른 유전자를 선택적으로 발현하여 특정한 형태와 기능을 가진 세포가 된다.',
  ['분화 과정에서 필요 없는 유전자는 DNA에서 영구히 제거된다.', '세포마다 서로 다른 유전체를 물려받아 분화한다.',
   '분화된 세포는 모든 유전자를 똑같은 양으로 발현한다.', '세포 분화는 돌연변이가 일어날 때만 일어난다.'],
  ['한 수정란에서 체세포 분열로 생긴 세포들은 같은 유전체를 가진다.',
   '세포마다 발현되는 유전자가 달라(선택적 유전자 발현) 근육 세포, 신경 세포 등으로 분화한다.',
   '분화된 세포에도 모든 유전자가 남아 있으며, 분화는 돌연변이가 아니라 발현 조절로 일어난다.'])

q(T, 2, '다음 중 사람의 이자 β세포와 눈의 수정체 세포에서 모두 발현되는 유전자로 가장 적절한 것은?',
  '해당 과정에 관여하는 효소의 유전자',
  ['인슐린 유전자', '크리스탈린(수정체 단백질) 유전자', '헤모글로빈 유전자', '근육 마이오신 유전자'],
  ['세포 호흡의 해당 과정 효소처럼 생명 유지에 필요한 단백질의 유전자는 대부분의 세포에서 발현된다.',
   '인슐린 유전자는 이자 β세포에서, 크리스탈린 유전자는 수정체 세포에서만 발현된다.',
   '헤모글로빈 유전자는 적혈구가 되는 세포, 마이오신 유전자는 근육 세포에서 주로 발현된다. 그러나 이 유전자들은 모든 체세포의 유전체에 들어 있다.'])

q(T, 3, '올챙이의 창자 세포에서 핵을 꺼내, 핵을 제거한 개구리의 난자에 이식하였더니 일부가 정상적인 올챙이로 발생하였다. 이 실험 결과로부터 알 수 있는 것으로 가장 적절한 것은?',
  '분화된 세포의 핵에도 개체 발생에 필요한 유전 정보가 모두 들어 있다.',
  ['창자 세포는 분화 과정에서 창자에 필요한 유전자만 남기고 나머지를 잃었다.', '개체 발생에 필요한 유전 정보는 난자의 세포질에만 들어 있다.',
   '분화된 세포의 핵은 다시는 다른 세포로 분화할 수 없다.', '올챙이의 창자 세포는 난자와 다른 종의 유전체를 가진다.'],
  ['창자 세포는 이미 분화한 세포인데, 그 핵으로 올챙이 전체가 발생하였다.',
   '따라서 분화된 세포의 핵에도 모든 종류의 세포를 만드는 데 필요한 유전 정보가 남아 있음을 알 수 있다.',
   '분화는 유전자를 잃는 것이 아니라 발현 조절의 차이이며, 적절한 환경(난자 세포질)에서는 핵이 다시 여러 세포로 분화할 수 있다.'])

_gene4 = {'X': 'ab', 'Y': 'ac', 'Z': 'bcd'}
_cell4 = {'Ⅰ': 'AB', 'Ⅱ': 'ACD', 'Ⅲ': 'BCD'}
_on4 = lambda c: [g for g, s in _gene4.items() if all(x.upper() in _cell4[c] for x in s)]
assert _on4('Ⅰ') == ['X'] and _on4('Ⅱ') == ['Y'] and _on4('Ⅲ') == ['Z']
q(T, 3, '표는 유전자 X~Z의 전사 조절 부위와, 세포 Ⅰ~Ⅲ에 있는 전사 인자를 나타낸 것이다. 전사 인자 A~D는 각각 조절 부위 a~d에만 결합하며, 각 유전자는 자신의 조절 부위에 결합하는 전사 인자가 모두 있을 때만 전사된다.\n\n'
  '| 유전자 | 조절 부위 |\n' + '\n'.join(f'| {g} | {", ".join(s)} |' for g, s in _gene4.items()) +
  '\n\n| 세포 | 있는 전사 인자 |\n' + '\n'.join(f'| {c} | {", ".join(s)} |' for c, s in _cell4.items()) +
  '\n\n세포 Ⅱ에서 전사되는 유전자만을 있는 대로 고른 것은?',
  'Y', ['X', 'Z', 'X, Y', 'Y, Z'],
  ['Ⅱ에는 A, C, D가 있다.',
   'X는 a, b가 모두 필요한데 B가 없어 전사되지 않고, Y는 a, c에 A, C가 모두 결합하므로 전사된다.',
   'Z는 b, c, d가 필요한데 B가 없어 전사되지 않는다. 따라서 Y만 전사된다.'])

q(T, 4, '다음은 근육 세포 분화에 대한 실험이다.\n\n'
  '(가) MyoD 유전자는 근육 세포로 분화할 세포에서 발현되며, MyoD 단백질은 전사 인자이다.\n'
  '(나) 근육 세포가 아닌 섬유아세포에 MyoD 유전자를 넣어 발현시켰더니, 섬유아세포에서 마이오신 등 근육 특이 단백질이 합성되고 근육 세포와 비슷한 세포로 변하였다.\n\n'
  '이에 대한 설명으로 옳은 것은?',
  '섬유아세포의 유전체에도 마이오신 유전자가 들어 있다.',
  ['MyoD 유전자를 넣으면 섬유아세포의 유전체에 마이오신 유전자가 새로 생긴다.',
   'MyoD 단백질은 마이오신 mRNA를 분해하여 근육 분화를 억제한다.',
   '섬유아세포는 원래 모든 근육 특이 유전자를 발현하고 있었다.',
   'MyoD 단백질은 번역 단계에서만 작용하는 효소이다.'],
  ['섬유아세포에 넣은 것은 MyoD 유전자뿐인데 마이오신이 합성되었으므로, 마이오신 유전자는 원래 섬유아세포의 유전체에 있었다.',
   'MyoD 단백질은 전사 인자로서 근육 특이 유전자들의 전사를 촉진한다. 이처럼 여러 유전자의 발현을 한꺼번에 켜서 분화를 이끄는 유전자를 핵심 조절 유전자라 한다.',
   '섬유아세포는 원래 근육 특이 유전자를 발현하지 않았기 때문에 근육 단백질이 없었다.'])

_gene5 = {'w': 'ab', 'x': 'ac', 'y': 'bd', 'z': 'cd'}
_obs5 = {'Ⅰ': {'w', 'x'}, 'Ⅱ': {'y', 'z'}, 'Ⅲ': {'x', 'z'}}
_on5 = lambda tf: {g for g, s in _gene5.items() if all(x.upper() in tf for x in s)}
_sets = {}
for c, ob in _obs5.items():
    fits = [set(tf) for r in range(5) for tf in itertools.combinations('ABCD', r) if _on5(set(tf)) == ob]
    assert len(fits) == 1, (c, fits)
    _sets[c] = fits[0]
assert _sets == {'Ⅰ': set('ABC'), 'Ⅱ': set('BCD'), 'Ⅲ': set('ACD')}
assert all('C' in s for s in _sets.values())
assert _on5(_sets['Ⅱ'] - {'B'}) == {'z'} and _on5(_sets['Ⅲ'] - {'D'}) == {'x'}
HB(T, 5, '표는 유전자 w~z의 전사 조절 부위와, 세포 Ⅰ~Ⅲ에서 전사되는 유전자를 나타낸 것이다. 전사 인자 A~D는 각각 조절 부위 a~d에만 결합하며, 각 유전자는 자신의 조절 부위에 결합하는 전사 인자가 모두 있을 때만 전사된다.\n\n'
   '| 유전자 | 조절 부위 |\n' + '\n'.join(f'| {g} | {", ".join(s)} |' for g, s in _gene5.items()) +
   '\n\n| 세포 | 전사되는 유전자 |\n' + '\n'.join(f'| {c} | {", ".join(sorted(s))} |' for c, s in _obs5.items()) +
   '\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은? (단, 제시된 유전자 외의 조건은 고려하지 않는다.)',
   [('전사 인자 C는 Ⅰ~Ⅲ에 모두 있다.', True,
     'Ⅰ은 w, x가 전사되고 y, z는 전사되지 않으므로 A, B, C가 있고 D가 없다. 같은 방법으로 Ⅱ는 B, C, D, Ⅲ은 A, C, D를 가지므로 C는 모두에 있다'),
    ('Ⅱ에서 전사 인자 B가 없어지면 전사되는 유전자는 하나도 없다.', False,
     'Ⅱ에서 B가 없어지면 C, D만 남아 z(c, d)는 여전히 전사된다'),
    ('Ⅲ에서 전사 인자 D가 없어지면 전사되는 유전자는 하나도 없다.', False,
     'Ⅲ에서 D가 없어지면 A, C만 남아 x(a, c)는 여전히 전사된다')],
   expect='ㄱ')

# ═══════════════════════════════════════════════════════════
# T16  u1m1s1t3  발생 과정 유전자 발현 조절 해석
