# T18  u2m0s0t0  제한 효소와 DNA 연결 효소 작용 이해
# ═══════════════════════════════════════════════════════════
T = 'u2m0s0t0'
q(T, 1, '제한 효소에 대한 설명으로 옳은 것은?',
  'DNA의 특정 염기 서열을 인식하여 그 부위를 자르는 효소이다.',
  ['끊어진 DNA 조각의 당-인산 골격을 이어 붙이는 효소이다.', 'RNA를 주형으로 DNA를 합성하는 효소이다.',
   'DNA를 주형으로 RNA를 합성하는 효소이다.', 'DNA 이중 나선의 수소 결합을 끊어 두 가닥으로 풀어 주는 효소이다.'],
  ['제한 효소는 DNA에서 특정 염기 서열(인식 서열)을 찾아 자르는 효소로, 유전자 재조합의 "가위" 역할을 한다.',
   'DNA 조각을 이어 붙이는 것은 DNA 연결 효소, RNA를 주형으로 DNA를 만드는 것은 역전사 효소이다.',
   'DNA를 주형으로 RNA를 합성하는 것은 RNA 중합 효소이다.'])

_oh = overhang('EcoRI')
q(T, 2, "제한 효소 EcoRI은 5'-G↓AATTC-3' 서열을 인식하여 화살표 위치를 자른다(상보 가닥도 같은 방식으로 잘린다). EcoRI으로 자른 DNA 조각의 끝에 생기는 한 가닥으로 된 부분(점착 말단)의 염기 서열(5'→3')은?",
  f"5'-{_oh}-3'", ["5'-GAATTC-3'", "5'-TTAA-3'", "5'-CTTAAG-3'", "5'-AAT-3'"],
  ["위 가닥은 G와 AATTC 사이가 잘리고, 상보 가닥도 5'-G↓AATTC-3'에서 잘린다.",
   f"그 결과 각 조각 끝에 5'-{_oh}-3'이 한 가닥으로 튀어나온 점착 말단이 생긴다.",
   "5'-TTAA-3'은 방향을 거꾸로 읽은 것이며, 인식 서열 6개 전체가 한 가닥으로 남지는 않는다."])

_n = 3
q(T, 3, f'제한 효소 X의 인식 자리가 {_n}곳 있는 선형 DNA와, 인식 자리가 {_n}곳 있는 원형 플라스미드를 각각 X로 완전히 잘랐다. 생기는 DNA 조각 수를 옳게 짝지은 것은?',
  f'선형 DNA: {_n + 1}개, 원형 플라스미드: {_n}개',
  [f'선형 DNA: {_n}개, 원형 플라스미드: {_n + 1}개', f'선형 DNA: {_n}개, 원형 플라스미드: {_n}개',
   f'선형 DNA: {_n + 1}개, 원형 플라스미드: {_n + 1}개', f'선형 DNA: {_n + 1}개, 원형 플라스미드: {_n - 1}개'],
  [f'선형 DNA는 양 끝이 있으므로 {_n}곳을 자르면 {_n + 1}개의 조각이 생긴다.',
   f'원형 DNA는 끝이 없으므로 {_n}곳을 자르면 {_n}개의 조각이 생긴다(한 곳만 자르면 선형 DNA 1개).',
   '선형과 원형을 반대로 계산하지 않도록 주의한다.'])

q(T, 3, '제한 효소와 DNA 연결 효소에 대한 설명으로 옳지 «않은» 것은?',
  'DNA 연결 효소는 두 DNA 조각 사이에 수소 결합만 형성하여 조각을 연결한다.',
  ['제한 효소는 원래 세균이 침입한 바이러스의 DNA를 자르는 데 쓰인다.',
   '같은 제한 효소로 자른 DNA 조각들은 점착 말단이 상보적이어서 서로 결합할 수 있다.',
   '제한 효소의 인식 서열은 대개 두 가닥을 각각 5\'→3\'으로 읽을 때 같은 회문 구조이다.',
   '제한 효소의 종류에 따라 인식하는 염기 서열이 다르다.'],
  ['점착 말단의 염기끼리는 수소 결합으로 저절로 짝을 짓지만, 당-인산 골격의 끊어진 부분은 DNA 연결 효소가 공유 결합으로 이어 준다.',
   '따라서 연결 효소가 수소 결합만 만든다는 설명은 틀렸다.',
   '제한 효소는 세균의 방어 수단이며, 효소마다 인식 서열이 다르고 대개 회문 구조이다.'])

_seq = 'CGGATCCTAAAGCTTGCGAATTCATGGATCCAGT'
_b, _h, _e = sites(_seq, 'BamHI'), sites(_seq, 'HindIII'), sites(_seq, 'EcoRI')
assert (_b, _h, _e) == ([1, 25], [9], [17])
_nf = len(_b) + len(_h) + 1
assert _nf == 4
q(T, 4, "다음은 선형 이중 가닥 DNA의 한 가닥을 5'→3' 방향으로 나타낸 것이고, 표는 제한 효소의 인식 서열이다.\n\n"
  f"5'-{_seq}-3'\n\n| 제한 효소 | 인식 서열(5'→3') |\n| BamHI | GGATCC |\n| HindIII | AAGCTT |\n| EcoRI | GAATTC |\n\n"
  '이 DNA를 BamHI과 HindIII로 함께 완전히 자를 때 생기는 DNA 조각의 수는?',
  f'{_nf}개', [f'{_nf - 1}개', f'{_nf + 1}개', f'{_nf - 2}개', f'{_nf + 2}개'],
  [f'BamHI 인식 서열 GGATCC는 {len(_b)}곳, HindIII 인식 서열 AAGCTT는 {len(_h)}곳에 있다(EcoRI 자리는 이 처리와 관계없다).',
   f'선형 DNA를 모두 {len(_b) + len(_h)}곳에서 자르므로 조각은 {len(_b) + len(_h)} + 1 = {_nf}개이다.',
   '인식 서열은 회문 구조이므로 한 가닥에서 찾은 자리가 곧 이중 가닥 DNA의 절단 자리이다.'])

_j1, _j2 = 'G' + 'GATC' + 'T', 'A' + 'GATC' + 'C'
assert _j1 == 'GGATCT' and 'GGATCC' not in (_j1, _j2) and 'AGATCT' not in (_j1, _j2)
assert overhang('EcoRI') != overhang('BamHI')
HB(T, 5, "표는 제한 효소 BamHI, BglII, EcoRI의 인식 서열과 절단 위치(↓)를 나타낸 것이다. 각 효소는 상보 가닥도 같은 방식으로 자른다.\n\n"
   "| 제한 효소 | 인식 서열과 절단 위치 |\n| BamHI | 5'-G↓GATCC-3' |\n| BglII | 5'-A↓GATCT-3' |\n| EcoRI | 5'-G↓AATTC-3' |\n\n"
   '이에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은?',
   [('BamHI으로 자른 말단과 BglII로 자른 말단은 점착 말단이 상보적이어서 DNA 연결 효소로 연결될 수 있다.', True,
     "두 효소 모두 5'-GATC-3' 점착 말단을 만들므로 서로 상보적으로 결합한다"),
    ("BamHI 말단과 BglII 말단이 연결되어 생긴 부위(5'-GGATCT-3')는 BamHI으로 다시 자를 수 있다.", False,
     'GGATCT는 BamHI의 인식 서열(GGATCC)도, BglII의 인식 서열(AGATCT)도 아니므로 두 효소 모두 다시 자르지 못한다'),
    ('EcoRI으로 자른 말단과 BamHI으로 자른 말단은 DNA 연결 효소로 연결될 수 있다.', False,
     "EcoRI 말단(AATT)과 BamHI 말단(GATC)은 상보적이지 않아 점착 말단끼리 결합하지 못한다")],
   expect='ㄱ')

