q(T, 2, '재조합 DNA를 만들 때 유용한 유전자와 플라스미드를 같은 제한 효소로 자르는 까닭으로 옳은 것은?',
  '서로 상보적인 점착 말단이 생겨 두 DNA 조각이 결합할 수 있기 때문이다.',
  ['같은 효소로 자르면 DNA 연결 효소가 필요 없기 때문이다.', '플라스미드의 항생제 저항성 유전자를 제거하기 위해서이다.',
   '유전자의 인트론을 제거하기 위해서이다.', '같은 효소로 잘라야 DNA가 복제되지 않기 때문이다.'],
  ['같은 제한 효소로 자르면 양쪽 DNA 끝에 같은(서로 상보적인) 점착 말단이 생긴다.',
   '점착 말단끼리 염기쌍을 이룬 뒤 DNA 연결 효소가 당-인산 골격을 이어 재조합 DNA가 완성된다.',
   '연결 효소는 여전히 필요하며, 제한 효소가 인트론을 제거하지는 않는다.'])

q(T, 3, '어떤 유용한 유전자 X를 잘라 내어 플라스미드에 넣으려고 한다. 사용할 제한 효소를 고를 때 가장 적절한 기준은?',
  'X의 안쪽은 자르지 않고 X의 양옆을 자르며, 플라스미드에서는 선별에 필요한 유전자 밖의 한 곳을 자르는 효소',
  ['X의 한가운데를 여러 번 자르는 효소', '플라스미드의 복제 원점을 자르는 효소',
   '플라스미드의 항생제 저항성 유전자(선별에 쓸 유전자)를 반드시 자르는 효소', '인식 서열이 짧아 X와 플라스미드를 가능한 한 많은 곳에서 자르는 효소'],
  ['X를 온전하게 얻으려면 X의 내부에는 인식 서열이 없고 양옆에만 있는 효소를 써야 한다.',
   '플라스미드는 복제 원점과 선별에 쓸 유전자가 망가지지 않도록, 그 밖의 한 곳만 자르는 효소가 좋다.',
   '여러 곳을 자르면 X나 플라스미드가 조각나 쓸 수 없게 된다.'])

q(T, 3, '재조합 DNA 제작 과정에 대한 설명으로 옳지 «않은» 것은?',
  '재조합 DNA는 반드시 같은 종의 DNA끼리만 만들 수 있다.',
  ['벡터로는 플라스미드나 바이러스의 DNA를 이용할 수 있다.',
   '재조합 플라스미드를 세균 안으로 넣는 과정을 형질 전환이라고 한다.',
   '유용한 유전자와 벡터를 같은 제한 효소로 자른다.',
   'DNA 연결 효소는 결합한 점착 말단 사이의 당-인산 골격을 연결한다.'],
  ['DNA는 모든 생물에서 같은 구조(뉴클레오타이드, 이중 나선)이므로 사람 유전자와 세균 플라스미드처럼 서로 다른 종의 DNA도 연결할 수 있다.',
   '이것이 사람 인슐린 유전자를 대장균에서 발현시킬 수 있는 까닭이다.',
   '나머지 설명은 모두 옳다.'])

q(T, 4, "플라스미드와 유전자 X를 각각 두 종류의 제한 효소 EcoRI(점착 말단 5'-AATT-3')과 BamHI(점착 말단 5'-GATC-3')으로 함께 잘랐다. X는 한쪽 끝이 EcoRI 말단, 다른 쪽 끝이 BamHI 말단이 되었고, 플라스미드는 EcoRI 자리와 BamHI 자리 사이의 작은 조각이 떨어져 나가 양 끝이 각각 EcoRI 말단과 BamHI 말단이 되었다.\n\n"
  '이 방법에 대한 설명으로 옳은 것은? (단, EcoRI 말단과 BamHI 말단은 서로 상보적이지 않다.)',
  'X는 플라스미드에 한 가지 방향으로만 연결된다.',
  ['잘린 플라스미드의 두 말단이 서로 연결되어 원래 플라스미드로 쉽게 되돌아간다.', 'X의 EcoRI 말단은 플라스미드의 BamHI 말단과 연결된다.',
   'X는 두 방향으로 같은 비율로 삽입된다.', '이 방법에서는 DNA 연결 효소가 필요 없다.'],
  ['EcoRI 말단은 EcoRI 말단끼리, BamHI 말단은 BamHI 말단끼리만 결합한다.',
   '따라서 X는 EcoRI 말단이 플라스미드의 EcoRI 말단에, BamHI 말단이 BamHI 말단에 붙는 한 가지 방향으로만 삽입된다.',
   '잘린 플라스미드의 두 말단은 서로 상보적이지 않아 스스로 연결되기 어렵다. 점착 말단이 결합한 뒤에도 DNA 연결 효소가 있어야 골격이 이어진다.'])

_vec, _ins = 4000, 1200
_rec = _vec + _ins
assert _rec == 5200
HB(T, 5, f'크기가 {_vec:,} bp이고 앰피실린 저항성 유전자를 가진 플라스미드를 EcoRI으로 잘랐다. 이 플라스미드에는 EcoRI 인식 자리가 앰피실린 저항성 유전자 밖에 1곳 있다. 여기에 양 끝이 EcoRI 말단인 {_ins:,} bp의 DNA 조각 X를 섞고 DNA 연결 효소를 넣었다.\n\n'
   '이에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은? (단, 플라스미드 1분자에 X는 최대 1개만 삽입된다.)',
   [('X가 삽입되지 않고 다시 원래대로 연결된 플라스미드를 가진 대장균은 앰피실린이 든 배지에서 자라지 못한다.', False,
     '원래대로 연결된 플라스미드에도 앰피실린 저항성 유전자가 있으므로 앰피실린 배지에서 자란다'),
    (f'X가 삽입된 재조합 플라스미드를 다시 EcoRI으로 완전히 자르면 {_vec:,} bp와 {_ins:,} bp의 두 조각이 생긴다.', True,
     f'재조합 플라스미드({_rec:,} bp)에는 X 양옆에 EcoRI 자리가 2곳 있으므로 원형 DNA가 두 조각({_vec:,} bp, {_ins:,} bp)으로 잘린다'),
    ('X는 플라스미드에 두 가지 방향으로 삽입될 수 있다.', True,
     'X의 양 끝이 모두 같은 EcoRI 말단이므로 X가 뒤집힌 방향으로도 연결될 수 있다')],
   expect='ㄴ, ㄷ')

