# T21  u2m0s0t3  유전자 클로닝 단계 순서 해석
# ═══════════════════════════════════════════════════════════
T = 'u2m0s0t3'
q(T, 1, '유전자 클로닝에 대한 설명으로 옳은 것은?',
  '특정 유전자를 벡터에 넣어 숙주 세포에서 증식시켜 같은 유전자를 대량으로 얻는 것이다.',
  ['체세포의 핵을 난자에 이식하여 개체를 복제하는 것이다.', '유전자의 염기 서열을 무작위로 바꾸는 것이다.',
   'mRNA를 단백질로 번역하는 과정이다.', '염색체의 수를 두 배로 늘리는 것이다.'],
  ['유전자 클로닝은 원하는 유전자를 벡터에 넣고 세균 등 숙주 세포에서 증식시켜, 똑같은 유전자(또는 그 산물)를 많이 얻는 기술이다.',
   '핵을 이식하여 개체를 만드는 것은 개체 복제(핵치환)이다.',
   '번역이나 염색체 배수화와는 다른 개념이다.'])

_ok = '(나) → (다) → (가) → (라)'
_ch = ['(다) → (나) → (가) → (라)', '(가) → (나) → (다) → (라)', '(나) → (가) → (다) → (라)', _ok, '(나) → (다) → (라) → (가)']
assert len(set(_ch)) == 5
qf(T, 2, '다음은 대장균을 이용한 유전자 클로닝 과정의 일부를 순서 없이 나타낸 것이다.\n\n'
   '(가) 재조합 플라스미드를 대장균에 넣는다(형질 전환).\n'
   '(나) 유용한 유전자와 플라스미드를 같은 제한 효소로 자른다.\n'
   '(다) DNA 연결 효소로 유용한 유전자와 플라스미드를 연결한다.\n'
   '(라) 항생제 배지 등에서 원하는 대장균을 골라 배양한다.\n\n'
   '순서대로 옳게 나열한 것은?',
   _ch, 3,
   ['먼저 같은 제한 효소로 자르고(나), DNA 연결 효소로 이어 재조합 플라스미드를 만든다(다).',
    '재조합 플라스미드를 대장균에 넣은 뒤(가), 선별 배지에서 원하는 대장균을 골라 증식시킨다(라).',
    '대장균이 분열할 때마다 재조합 플라스미드도 복제되어 유전자가 대량으로 늘어난다.'])

q(T, 3, '유전자 클로닝의 각 단계와 그 단계에 필요한 것을 옳게 짝지은 것은?',
  '유용한 유전자와 벡터의 연결 – DNA 연결 효소',
  ['DNA 자르기 – DNA 연결 효소', '유용한 유전자와 벡터의 연결 – 역전사 효소',
   '원하는 대장균 선별 – 제한 효소', '재조합 플라스미드를 대장균에 넣기 – 방출 인자'],
  ['DNA를 자르는 데는 제한 효소, 자른 조각을 잇는 데는 DNA 연결 효소가 쓰인다.',
   '원하는 대장균의 선별에는 항생제 등 선별 배지가 쓰인다.',
   '역전사 효소는 mRNA로부터 DNA(cDNA)를 만들 때, 방출 인자는 번역 종결 때 작용한다.'])

q(T, 3, '대장균을 이용한 유전자 클로닝에 대한 설명으로 옳지 «않은» 것은?',
  '형질 전환 과정을 거친 대장균은 모두 재조합 플라스미드를 가지고 있다.',
  ['형질 전환 과정에서 플라스미드를 받아들이는 대장균은 일부뿐이다.',
   '대장균이 분열할 때 재조합 플라스미드도 복제되어 딸세포로 전달된다.',
   '선별 배지를 이용하여 재조합 플라스미드를 가진 대장균을 골라낸다.',
   '골라낸 대장균을 배양하면 유용한 유전자의 산물을 대량으로 얻을 수 있다.'],
  ['형질 전환 과정을 거쳐도 플라스미드를 받아들이지 못한 대장균, 유전자가 삽입되지 않은 플라스미드를 가진 대장균이 섞여 있다.',
   '그래서 항생제 배지 등을 이용한 선별 단계가 필요하다.',
   '선별한 대장균은 분열하면서 재조합 플라스미드를 복제하여 유전자와 그 산물을 대량으로 만든다.'])

q(T, 4, '연구자가 사람 세포의 유전체 DNA에서 성장 호르몬 유전자를 잘라 내어 플라스미드에 넣고 대장균에 도입하였다. 재조합 플라스미드를 가진 대장균을 골라 배양하였으나 기능을 가진 성장 호르몬이 만들어지지 않았다. 이 문제를 해결하는 방법으로 가장 적절한 것은?',
  '성장 호르몬 mRNA로부터 역전사 효소를 이용해 만든 DNA(cDNA)를 플라스미드에 넣는다.',
  ['제한 효소를 더 많이 넣어 유전체 DNA를 잘게 자른다.', '대장균 대신 플라스미드가 없는 대장균을 숙주로 쓴다.',
   '앰피실린 저항성 유전자를 제거한 플라스미드를 쓴다.', 'DNA 연결 효소를 넣지 않고 재조합 플라스미드를 만든다.'],
  ['사람 유전체 DNA의 유전자에는 인트론이 있는데, 대장균은 인트론을 제거하는 RNA 가공을 하지 못한다.',
   '그래서 인트론이 포함된 채로 번역되어 정상 단백질이 만들어지지 않는다.',
   '이미 인트론이 제거된 성숙한 mRNA를 역전사 효소로 DNA(cDNA)로 바꾸어 넣으면 대장균에서도 정상 단백질을 만들 수 있다.'])

_gen = 120 // 20
assert 2 ** _gen == 64
HB(T, 5, '대장균을 이용한 유전자 클로닝에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은?',
   [('형질 전환 단계에서는 배양액 속의 모든 대장균이 재조합 플라스미드를 받아들인다.', False,
     '플라스미드를 받아들이는 대장균은 일부뿐이며, 그래서 선별 과정이 필요하다'),
    ('재조합 플라스미드는 대장균이 분열해도 복제되지 않으므로 딸세포에 전달되지 않는다.', False,
     '플라스미드는 복제 원점이 있어 스스로 복제되며 딸세포에 전달된다'),
    (f'재조합 플라스미드를 가진 대장균 1개가 20분마다 한 번씩 분열한다면, 2시간 뒤 이 플라스미드를 가진 대장균은 {2 ** _gen}개가 된다.', True,
     f'2시간(120분) 동안 {_gen}번 분열하므로 2^{_gen} = {2 ** _gen}개가 된다')],
   expect='ㄷ')

