  f"이 부위 전체를 증폭하기 위한 프라이머 쌍으로 옳은 것은? (단, 프라이머는 {_k}개의 뉴클레오타이드로 이루어지며, 5'→3' 방향으로 나타낸다.)",
  f"5'-{_F}-3'과 5'-{_R}-3'",
