# T27  u2m1s0t0  유전자 치료 원리와 사례 분석
# ═══════════════════════════════════════════════════════════
T = 'u2m1s0t0'
q(T, 1, '유전자 치료에 대한 설명으로 옳은 것은?',
  '결함이 있는 유전자 때문에 생긴 질병을 치료하기 위해 정상 유전자를 환자의 세포에 넣어 주는 방법이다.',
  ['환자에게 부족한 단백질을 주사로 계속 보충하는 방법이다.', '환자의 장기를 다른 사람의 장기로 바꾸는 방법이다.',
   '항생제로 병원균의 DNA를 파괴하는 방법이다.', '환자의 모든 세포에서 유전체 전체를 새것으로 바꾸는 방법이다.'],
  ['유전자 치료는 유전자 이상으로 생긴 질병을 치료하기 위해 정상 유전자를 세포에 넣거나 결함 유전자를 교정하는 방법이다.',
   '단백질을 주사하는 것은 증상을 보완하는 치료이고, 장기 이식이나 항생제 치료는 유전자 치료가 아니다.',
   '유전체 전체를 바꾸는 것이 아니라 특정 유전자를 다룬다.'])

q(T, 2, '유전자 치료에서 바이러스를 유전자 운반체(벡터)로 이용할 때에 대한 설명으로 옳은 것은?',
  '바이러스의 병을 일으키는 유전자를 제거하고 치료용 유전자를 넣어, 세포 안으로 유전자를 효율적으로 전달한다.',
  ['병을 일으키는 능력을 그대로 가진 바이러스를 사용해야 한다.', '바이러스는 스스로 치료용 단백질을 만들어 혈액으로 분비한다.',
   '바이러스를 이용하면 유전자가 생식세포로만 전달된다.', '바이러스 벡터는 세포막을 통과하지 못하므로 세포 밖에서 작용한다.'],
  ['바이러스는 숙주 세포 안으로 자신의 유전 물질을 넣는 능력이 뛰어나다.',
   '이 능력은 살리고 병원성 유전자는 제거한 뒤 치료용 유전자를 넣어 운반체로 쓴다.',
   '치료용 단백질은 유전자가 들어간 환자의 세포가 만든다.'])

q(T, 3, '유전자 치료 방법에 대한 설명으로 옳은 것은?',
  '체외 유전자 치료는 환자의 세포를 몸 밖으로 꺼내 정상 유전자를 넣은 뒤 다시 몸속에 넣는 방법이다.',
  ['체내 유전자 치료는 환자의 세포를 몸 밖에서 배양한 뒤 다시 넣는 방법이다.',
   '체외 유전자 치료에서는 유전자 운반체가 필요 없다.',
   '모든 유전자 치료는 수정란의 유전자를 바꾸는 방법이다.',
   '체외 유전자 치료로 바뀐 유전자는 반드시 자손에게 전달된다.'],
  ['체외(ex vivo) 유전자 치료: 환자 세포를 꺼내 정상 유전자를 넣고 확인한 뒤 다시 넣는다.',
   '체내(in vivo) 유전자 치료: 유전자를 넣은 운반체를 환자 몸속에 직접 주입한다. 두 방법 모두 운반체가 쓰인다.',
   '체세포를 다루는 치료이므로 바뀐 유전자는 자손에게 전달되지 않는다.'])

q(T, 3, '다음은 유전자 치료 사례이다.\n\n'
  '1990년, ADA 효소를 만드는 유전자에 이상이 있어 면역 기능이 매우 약한 어린이에게 유전자 치료가 시도되었다. 환자의 혈액에서 T 림프구를 분리한 뒤 정상 ADA 유전자를 넣고 배양하여 다시 환자의 몸속에 넣었다.\n\n'
  '이 사례에 대한 설명으로 옳지 «않은» 것은?',
  '이 치료를 받은 환자의 자녀는 정상 ADA 유전자를 물려받는다.',
  ['체외 유전자 치료에 해당한다.', 'T 림프구에 유전자를 넣을 때 바이러스 운반체를 이용할 수 있다.',
   'T 림프구는 수명이 있으므로 효과를 유지하려면 치료를 반복해야 할 수 있다.', '치료 목표는 환자의 세포가 ADA 효소를 만들게 하는 것이다.'],
  ['유전자를 넣은 것은 체세포인 T 림프구이므로 생식세포에는 정상 ADA 유전자가 없다. 따라서 자녀에게 전달되지 않는다.',
   '세포를 꺼내 유전자를 넣고 다시 넣었으므로 체외 유전자 치료이며, 유전자 전달에 바이러스 운반체가 쓰일 수 있다.',
   '성숙한 T 림프구는 계속 새로 만들어지는 세포가 아니어서 시간이 지나면 줄어들므로 치료를 반복해야 할 수 있다.'])

_d = {'Ⅰ': [30, 20, 8, 1], 'Ⅱ': [25, 25, 26, 25]}
assert _d['Ⅰ'][-1] < _d['Ⅰ'][0] and max(_d['Ⅱ']) - min(_d['Ⅱ']) <= 1
q(T, 4, '다음은 혈액 세포의 유전자 이상으로 생기는 질환의 체외 유전자 치료 방법을 비교한 가상의 자료이다. 방법 Ⅰ은 성숙한 T 림프구에, 방법 Ⅱ는 골수의 조혈 모세포(모든 혈액 세포를 만드는 줄기세포)에 정상 유전자를 넣어 몸속에 되돌려 주었다. 표는 치료 후 혈액 속 백혈구 중 정상 유전자를 가진 세포의 비율(%)이다.\n\n'
  '| 방법 | 1개월 | 6개월 | 12개월 | 24개월 |\n' + '\n'.join(f'| {k} | ' + ' | '.join(map(str, v)) + ' |' for k, v in _d.items()) +
  '\n\n이 자료에 대한 해석으로 가장 적절한 것은?',
  '조혈 모세포는 분열을 계속하며 정상 유전자를 가진 혈액 세포를 꾸준히 만들어 내므로 효과가 오래 유지된다.',
  ['방법 Ⅰ의 효과가 시간이 지날수록 커진다.', '방법 Ⅱ로 넣은 유전자는 환자의 자녀에게 전달된다.',
   '성숙한 T 림프구는 스스로 분열하여 줄기세포가 된다.', '두 방법 모두 24개월 뒤 정상 유전자를 가진 세포가 거의 없다.'],
  ['방법 Ⅰ은 30%에서 1%로 줄었다. 성숙한 T 림프구는 수명이 있어 시간이 지나면 사라진다.',
   '방법 Ⅱ는 24개월 동안 약 25%로 유지되었다. 줄기세포인 조혈 모세포가 자기 복제와 분화를 계속하며 새 혈액 세포를 공급하기 때문이다.',
   '두 방법 모두 체세포를 다룬 것이므로 자녀에게 전달되지 않는다.'])

HB(T, 5, '유전자 치료에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은?',
   [('체세포 유전자 치료로 넣은 유전자는 환자의 자녀에게 전달되지 않는다.', True,
     '체세포의 유전자는 생식세포로 전달되지 않는다'),
    ('생식세포나 수정란의 유전자를 바꾸는 치료는 다음 세대에 영향을 주지 않으므로 윤리적 논란이 없다.', False,
     '생식세포·수정란의 변화는 자손에게 전달되어 다음 세대에 영향을 주므로 윤리적 논란이 크다'),
    ('바이러스 운반체가 넣은 유전자가 유전체의 어느 위치에 끼어드느냐에 따라 다른 유전자의 발현에 영향을 줄 수 있다.', True,
     '유전자가 다른 유전자 부근에 삽입되면 그 유전자의 발현을 바꿀 수 있어 안전성 검증이 필요하다')],
   expect='ㄱ, ㄷ')

