q(T, 3, '아그로박테리움을 이용하여 유전자 변형 식물을 만드는 과정에 대한 설명으로 옳은 것은?',
  'Ti 플라스미드에 유용한 유전자를 넣은 아그로박테리움을 식물 세포에 감염시키면, 유전자가 식물 세포의 염색체에 삽입될 수 있다.',
  ['아그로박테리움은 식물 세포의 염색체를 모두 없앤다.', '유전자를 넣은 식물 세포 하나는 완전한 식물체로 자랄 수 없다.',
   'Ti 플라스미드는 사람의 세포에서 얻는다.', '아그로박테리움은 식물 세포에 단백질만 넣고 DNA는 넣지 못한다.'],
  ['토양 세균인 아그로박테리움은 Ti 플라스미드의 일부 DNA를 식물 세포의 염색체에 끼워 넣는 성질이 있다.',
   '이 부분에 유용한 유전자를 넣으면 식물 세포에 그 유전자를 전달할 수 있다.',
   '유전자가 들어간 식물 세포는 조직 배양을 통해 완전한 식물체로 자랄 수 있다.'])

q(T, 3, '유전자 변형 생물체(GMO)의 사례와 그 원리를 설명한 것으로 옳지 «않은» 것은?',
  '황금쌀은 비타민 C를 합성하는 유전자를 넣어 만든 벼이다.',
  ['제초제 저항성 콩은 제초제에 견디는 효소의 유전자를 넣어 만들었다.',
   'Bt 옥수수는 해충에 독성을 나타내는 단백질의 유전자를 넣어 만들었다.',
   '무르지 않는 토마토는 열매를 무르게 하는 효소의 유전자 발현을 억제하여 만들었다.',
   '빨리 자라는 연어는 성장 호르몬 유전자의 발현이 늘어나도록 유전자를 넣어 만들었다.'],
  ['황금쌀은 비타민 A의 전구 물질인 베타카로틴을 합성하는 유전자를 넣어 쌀알이 노란빛을 띠게 만든 벼이다.',
   '비타민 A 결핍 문제를 줄이기 위해 개발되었다.',
   '나머지 사례는 모두 옳게 설명하였다.'])

q(T, 4, '다음은 유전자 변형 식물을 만드는 실험이다.\n\n'
  '(가) 유용한 유전자 X와 카나마이신(항생제) 저항성 유전자 K를 함께 넣은 Ti 플라스미드를 아그로박테리움에 넣는다.\n'
  '(나) 이 아그로박테리움을 식물의 잎 조각에 감염시킨 뒤, 카나마이신이 든 배지에서 배양하였다.\n'
  '(다) 살아남은 세포를 조직 배양하여 식물체 30개를 얻었고, 이 중 24개에서 X의 단백질이 검출되었다.\n\n'
  '이에 대한 설명으로 가장 적절한 것은?',
  '(나)에서 카나마이신 배지를 쓴 것은 유전자가 들어간 식물 세포를 골라내기 위해서이다.',
  ['(나)에서 살아남은 세포는 Ti 플라스미드를 받지 못한 세포이다.', '(다)에서 X 단백질이 검출된 식물체의 비율은 24 %이다.',
   '유전자가 들어간 식물 세포는 완전한 식물체로 자랄 수 없다.', 'K는 X 단백질의 기능을 높이기 위해 넣었다.'],
  ['K가 들어간 세포만 카나마이신 배지에서 살아남으므로, K는 유전자가 들어간 세포를 골라내는 선별 표지 역할을 한다.',
   '(다)에서 X 단백질이 검출된 비율은 24 ÷ 30 = 0.8, 즉 80 %이다.',
   '식물 세포는 조직 배양으로 완전한 식물체가 될 수 있다(전형성능).'])

_self = collections.Counter()
for _a in ('T', '-'):
    for _b in ('T', '-'):
        _self[''.join(sorted(_a + _b))] += Fr(1, 4)
_expr = _self['TT'] + _self['-T']
_homo_among = _self['TT'] / _expr
_test = Fr(1, 2)
assert _expr == Fr(3, 4) and _homo_among == Fr(1, 3) and _test == Fr(1, 2)
HB(T, 5, '어떤 식물에 해충 저항성 유전자 R을 넣어 유전자 변형 식물 P를 얻었다. P에서 R은 한 쌍의 상동 염색체 중 한 염색체에만 1개 삽입되었고, R을 1개 이상 가지면 해충 저항성이 나타난다.\n\n'
   '이에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은? (단, 돌연변이와 교차는 고려하지 않는다.)',
   [(f'P를 자가 수분하여 얻은 자손 중 해충 저항성을 나타내는 개체의 비율은 1/2이다.', False,
     f'P는 R을 한 염색체에만 가지므로(R/−) 자가 수분하면 R/R : R/− : −/− = 1 : 2 : 1이고, 저항성 개체는 {_expr.numerator}/{_expr.denominator}이다'),
    (f'P를 자가 수분하여 얻은 자손 중 해충 저항성을 나타내는 개체에서 R을 2개 가진 개체의 비율은 1/2이다.', False,
     f'저항성 개체(R/R 1 : R/− 2) 중 R/R은 {_homo_among.numerator}/{_homo_among.denominator}이다'),
    ('P를 R이 없는 식물과 교배하면 자손의 1/2이 해충 저항성을 나타낸다.', True,
     'R/− × −/− → R/− : −/− = 1 : 1이므로 1/2이다')],
   expect='ㄷ')

