# T31  u2m1s0t4  생명공학 활용 사례 자료 해석
# ═══════════════════════════════════════════════════════════
T = 'u2m1s0t4'
q(T, 1, '당뇨병 치료에 쓰는 사람의 인슐린을 대장균으로 대량 생산하는 데 이용된 핵심 기술은?',
  '유전자 재조합 기술', ['단일 클론 항체 기술', '핵치환(체세포 복제) 기술', 'DNA 지문 분석', '젤 전기영동'],
  ['사람 인슐린 유전자를 플라스미드에 넣어 재조합 DNA를 만들고, 이를 대장균에 넣어 인슐린을 생산한다.',
   '이것은 유전자 재조합(클로닝) 기술의 대표적인 활용 사례이다.',
   '단일 클론 항체는 진단·치료용 항체, 핵치환은 개체 복제, DNA 지문 분석과 전기영동은 DNA 비교·분리에 쓰인다.'])

q(T, 2, 'RNA를 유전 물질로 가진 바이러스의 감염 여부를 PCR로 진단할 때에 대한 설명으로 옳은 것은?',
  '역전사 효소로 바이러스 RNA로부터 DNA를 만든 뒤, 이 DNA의 특정 부위를 PCR로 증폭하여 확인한다.',
  ['바이러스 RNA를 역전사 없이 DNA 중합 효소로 바로 증폭한다.', '환자의 항체를 PCR로 증폭한다.',
   '바이러스 단백질의 아미노산을 PCR로 증폭한다.', '프라이머 없이 바이러스 RNA 전체를 증폭한다.'],
  ['PCR에 쓰는 DNA 중합 효소는 DNA를 주형으로 쓰므로, RNA 바이러스는 먼저 역전사 효소로 RNA를 DNA로 바꾼다.',
   '그 뒤 바이러스에만 있는 부위에 결합하는 프라이머로 증폭하여 바이러스 유전 물질이 있는지 확인한다.',
   'PCR은 핵산을 증폭하는 기술이므로 항체나 단백질을 증폭하지 못한다.'])

q(T, 3, '다음은 복제 양 돌리를 만든 과정을 단순하게 나타낸 것이다.\n\n'
  '(가) 양 A의 젖샘 세포에서 핵을 꺼낸다.\n(나) 양 B의 난자에서 핵을 제거하고 (가)의 핵을 넣는다.\n(다) (나)의 세포를 발생시킨 초기 배아를 양 C의 자궁에 착상시켜 돌리가 태어났다.\n\n'
  '돌리의 핵 속 유전 정보는 누구와 같은가?',
  '양 A', ['양 B', '양 C', '양 A와 양 B의 유전 정보가 반씩 섞인 것', '양 B와 양 C의 유전 정보가 반씩 섞인 것'],
  ['돌리의 핵은 양 A의 젖샘 세포 핵에서 왔다.',
   '양 B는 핵을 제거한 난자(세포질)를, 양 C는 자궁(발생 장소)을 제공했을 뿐 핵 유전 정보를 주지 않았다.',
   '이 과정에는 정자와 난자의 수정이 없으므로 유전 정보가 반씩 섞이지 않는다.'])

q(T, 3, '생명공학기술과 그 활용 사례를 짝지은 것으로 옳지 «않은» 것은?',
  'PCR – 환자의 세포에 정상 유전자를 넣어 유전병을 치료한다.',
  ['유전자 재조합 – 대장균으로 사람의 성장 호르몬을 생산한다.', '단일 클론 항체 – 특정 암세포를 표적으로 하는 항암제를 만든다.',
   'DNA 지문 분석 – 범죄 현장의 시료로 용의자를 확인한다.', '조직 배양 – 유전자를 넣은 식물 세포를 완전한 식물체로 기른다.'],
  ['PCR은 DNA의 특정 부위를 증폭하는 기술로, 진단·DNA 분석 등에 쓰인다.',
   '환자의 세포에 정상 유전자를 넣어 치료하는 것은 유전자 치료이다.',
   '나머지는 모두 기술과 활용 사례를 옳게 짝지었다.'])

q(T, 4, '표는 당뇨병 치료용 인슐린을 얻는 두 방법을 비교한 자료이다.\n\n'
  '| 구분 | 방법 Ⅰ | 방법 Ⅱ |\n'
  '| 원료 | 도축한 돼지의 이자 | 사람 인슐린 유전자를 넣은 대장균 |\n'
  '| 사람 인슐린과의 차이 | 아미노산 1개가 다름 | 아미노산 서열이 같음 |\n'
  '| 생산량을 늘리는 방법 | 도축하는 돼지 수를 늘림 | 대장균 배양 규모를 늘림 |\n\n'
  '이 자료에 대한 설명으로 가장 적절한 것은?',
  '방법 Ⅱ는 사람 인슐린과 같은 단백질을 얻을 수 있고, 배양 규모를 늘려 생산량을 쉽게 늘릴 수 있다.',
  ['방법 Ⅰ로 얻은 인슐린은 사람 인슐린과 아미노산 서열이 완전히 같다.', '방법 Ⅱ에서는 대장균이 돼지의 인슐린 유전자를 발현한다.',
   '방법 Ⅱ는 유전자 재조합 기술과 관계가 없다.', '방법 Ⅰ은 방법 Ⅱ보다 원료를 구하기가 쉬워 생산량을 무한히 늘릴 수 있다.'],
  ['방법 Ⅱ는 사람 인슐린 유전자를 대장균에 넣은 유전자 재조합 기술로, 사람 인슐린과 아미노산 서열이 같은 단백질을 얻는다.',
   '대장균은 빠르게 증식하므로 배양 규모를 늘리면 생산량을 쉽게 늘릴 수 있다.',
   '방법 Ⅰ의 돼지 인슐린은 사람 인슐린과 아미노산 1개가 다르고, 원료가 도축 돼지 수에 제한된다.'])

_ctA, _ctB = 20, 25
_ratio = 2 ** (_ctB - _ctA)
assert _ratio == 32
HB(T, 5, f'RNA 바이러스 감염 여부를 알기 위해 시료 A~C에 역전사 과정을 거친 뒤 PCR을 하였다. 증폭된 DNA의 양이 일정한 기준값에 처음 도달한 주기 수를 측정하였고, 40주기까지 기준값에 도달하지 않으면 "검출 안 됨"으로 판정한다.\n\n'
   f'| 시료 | A | B | C |\n| 기준값 도달 주기 | {_ctA} | {_ctB} | 검출 안 됨 |\n\n'
   '이에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은? (단, 매 주기 DNA 양은 2배가 되며, 시료의 양과 반응 조건은 같다.)',
   [(f'처음 시료 속 표적 핵산의 양은 A가 B의 {_ratio}배이다.', True,
     f'A는 B보다 {_ctB - _ctA}주기 먼저 기준값에 도달했으므로 처음 양이 2^{_ctB - _ctA} = {_ratio}배 많다'),
    ('처음 시료 속 표적 핵산의 양은 B가 A보다 많다.', False,
     '기준값에 늦게 도달할수록 처음 양이 적은 것이므로 B가 A보다 적다'),
    ('역전사 과정 없이 바이러스 RNA를 DNA 중합 효소로 바로 증폭해도 같은 결과를 얻는다.', False,
     'PCR의 DNA 중합 효소는 DNA를 주형으로 쓰므로 RNA를 먼저 역전사하여 DNA로 만들어야 한다')],
   expect='ㄱ')

