T = 'u2m1s1t1'
q(T, 1, 'GMO의 개발과 이용을 찬성하는 쪽의 근거로 가장 적절한 것은?',
  '해충 저항성 작물을 재배하면 살충제 사용을 줄일 수 있다.',
  ['유전자 변형 작물의 유전자가 주변 야생종으로 퍼질 수 있다.', '새로운 단백질이 알레르기를 일으킬 수 있다.',
   '소수 기업이 종자를 독점할 수 있다.', '생물 다양성이 줄어들 수 있다.'],
  ['GMO 찬성 측은 수확량 증가, 농약 사용 감소, 영양 성분 강화 등을 근거로 든다.',
   '유전자 확산, 알레르기, 종자 독점, 생물 다양성 감소는 반대 측이 제기하는 우려이다.',
   '따라서 살충제 사용을 줄일 수 있다는 것이 찬성 측 근거이다.'])

q(T, 2, '제초제 저항성 유전자를 넣은 작물을 재배할 때 반대 측이 우려하는 생태계 문제로 가장 적절한 것은?',
  '꽃가루를 통해 제초제 저항성 유전자가 가까운 야생 잡초로 옮겨 가 제초제에 죽지 않는 잡초가 생길 수 있다.',
  ['제초제 저항성 작물은 광합성을 하지 못한다.', '제초제 저항성 작물을 먹으면 사람의 유전자가 곧바로 바뀐다.',
   '제초제 저항성 유전자는 어떤 생물로도 이동할 수 없다.', '제초제 저항성 작물은 씨를 맺지 못해 번식할 수 없다.'],
  ['유전자 변형 작물의 꽃가루가 가까운 근연종 잡초와 교배하면 삽입 유전자가 퍼질 수 있다(유전자 이동).',
   '제초제 저항성 유전자가 잡초로 옮겨 가면 제초제로 제거하기 어려운 잡초가 생길 수 있다는 우려가 있다.',
   '음식으로 먹은 DNA가 사람의 유전자를 바꾸지는 않는다.'])

q(T, 3, '유전자 변형 식품에 GMO 표시를 하도록 하는 제도의 주된 목적으로 가장 적절한 것은?',
  '소비자가 GMO 포함 여부를 알고 스스로 선택할 수 있도록 하기 위해서이다.',
  ['GMO가 모두 해롭다는 것을 과학적으로 증명하기 위해서이다.', 'GMO의 유전자를 제거하기 위해서이다.',
   'GMO의 생산량을 늘리기 위해서이다.', '식품의 맛을 좋게 하기 위해서이다.'],
  ['표시 제도는 소비자의 알 권리와 선택권을 보장하기 위한 것이다.',
   '표시 자체가 해롭다는 뜻은 아니며, 안전성은 별도의 평가 절차로 판단한다.',
   '표시는 유전자나 맛, 생산량과는 관계가 없다.'])

q(T, 3, 'GMO의 안전성 논쟁에 대한 설명으로 옳지 «않은» 것은?',
  'GMO는 한 번 승인되면 재배 후 생태계에 미치는 영향을 더 조사할 필요가 없다.',
  ['GMO는 사람의 건강과 환경에 미치는 영향을 평가하는 절차를 거쳐 승인된다.',
   '새로 넣은 유전자가 만드는 단백질이 알레르기를 일으키는지 검사한다.',
   '재배 후에도 주변 생태계에 미치는 영향을 계속 관찰할 필요가 있다.',
   '찬반 양측의 주장은 과학적 근거와 사회적 가치를 함께 고려하여 판단해야 한다.'],
  ['생태계 영향은 오랜 기간에 걸쳐 나타날 수 있으므로 승인 뒤에도 지속적으로 관찰해야 한다.',
   'GMO는 식품·환경 안전성 평가를 거치며, 알레르기 유발 가능성도 확인한다.',
   '따라서 승인 후 조사가 필요 없다는 설명은 틀렸다.'])

_y = {'1년째': (10, 100, 1), '5년째': (50, 60, 3), '10년째': (80, 40, 15)}
_r = _y['10년째'][2] / _y['1년째'][2]
assert _r == 15 and _y['10년째'][1] < _y['1년째'][1]
q(T, 4, '표는 어떤 지역에서 Bt 옥수수를 재배하기 시작한 뒤의 변화를 나타낸 가상의 자료이다.\n\n'
  '| 시기 | 전체 옥수수 중 Bt 옥수수 재배 비율(%) | 살충제 사용량(상댓값) | 해충 중 Bt 독소 저항성 개체 비율(%) |\n' +
  '\n'.join(f'| {k} | {a} | {b} | {c} |' for k, (a, b, c) in _y.items()) +
  '\n\n이 자료에 대한 해석으로 가장 적절한 것은?',
  'Bt 옥수수 재배 비율이 늘어날수록 살충제 사용량은 줄었지만, Bt 독소에 저항성인 해충의 비율은 늘었다.',
  ['Bt 옥수수 재배 비율과 살충제 사용량이 함께 늘었다.', 'Bt 독소 저항성 해충의 비율은 시간이 지날수록 줄었다.',
   '1년째에서 10년째까지 저항성 해충의 비율은 2배가 되었다.', '이 자료만으로 Bt 옥수수가 사람의 건강에 해롭다는 것이 증명된다.'],
  ['Bt 재배 비율은 10 → 50 → 80 %로 늘었고, 살충제 사용량은 100 → 60 → 40으로 줄었다.',
   f'저항성 해충 비율은 1 → 3 → 15 %로 늘어 1년째의 {int(_r)}배가 되었다. Bt 독소가 저항성 해충을 선택하는 압력으로 작용했음을 짐작할 수 있다.',
   '이 자료에는 사람의 건강에 대한 정보가 없다.'])

_d = {0: Fr(20, 10), 10: Fr(5, 10), 50: Fr(1, 10), 100: Fr(0)}
assert _d[10] / _d[0] == Fr(1, 4) and _d[100] == 0 and _d[50] > 0
HB(T, 5, '표는 제초제 저항성 유전자를 넣은 유채 재배지로부터 거리에 따라, 주변 일반 유채에서 얻은 씨 중 제초제 저항성 유전자를 가진 씨의 비율을 조사한 가상의 자료이다.\n\n'
   '| 재배지로부터의 거리(m) | 0 | 10 | 50 | 100 |\n| 저항성 유전자를 가진 씨의 비율(%) | 2.0 | 0.5 | 0.1 | 0 |\n\n'
   '이에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은? (단, 제시된 자료 외의 조건은 고려하지 않는다.)',
   [('거리가 10 m일 때 저항성 유전자를 가진 씨의 비율은 0 m일 때의 1/2이다.', False,
     '0.5 ÷ 2.0 = 1/4이다'),
    ('이 자료로 보아 유전자 변형 작물의 유전자는 주변 작물로 전혀 이동하지 않는다.', False,
     '10 m, 50 m에서도 저항성 유전자를 가진 씨가 나타났으므로 꽃가루 등을 통해 유전자가 이동하였다'),
    ('이 조사에서는 재배지로부터 100 m 떨어진 곳의 씨에서 저항성 유전자가 검출되지 않았다.', True,
     '100 m에서 비율이 0이다. 거리를 두는 것이 유전자 이동을 줄이는 한 방법이 될 수 있다')],
   expect='ㄷ')

