_st = {'A': ('보험사가 유전자 검사 결과를 이유로 가입을 거절하면 유전적 특성에 따른 차별이 될 수 있어.', True),
       'B': ('유전자 검사 결과는 질병이 생길지를 100 % 정확하게 알려 주니까 보험 심사에 반드시 써야 해.', False),
       'C': ('내 유전 정보에는 가족의 정보도 일부 들어 있으니, 동의 없이 다른 사람에게 제공되면 안 돼.', True)}
_ans = ', '.join(k for k, (_, t) in _st.items() if t)
assert _ans == 'A, C'
